d(r) as (select jsonb_array_elements($json$[{"k":"bal-a-breakfast","f":"balanced","d":"A","m":"breakfast","n":"Berry overnight oats","ds":"Creamy oats soaked overnight with Greek yoghurt, milk and berries. Make it before bed and breakfast is done.","pr":5,"ck":0,"st":["Grab a jar or container with a lid that holds at least 600 ml.","Add the rolled oats and chia seeds to the jar.","Pour in the milk and stir well so all the oats are wet. Scrape the bottom so no dry oats are hiding there.","Spoon in the Greek yoghurt and the honey and stir again until smooth.","Tip the frozen berries on top. No need to thaw them, they defrost overnight and the juice runs into the oats.","Put the lid on and leave it in the fridge for at least 4 hours, or overnight.","In the morning give it a stir. If it is too thick, add a splash of milk. Eat it cold straight from the jar."],"tp":"Make three jars on Sunday night for Monday, Wednesday and Friday. They keep for 3 days in the fridge.","dt":["vegetarian","pescatarian"],"c":501,"p":23.6,"cb":64.8,"ft":13.1,"ps":0,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Reduced fat milk",1,180,"3/4 cup",null,null],["Greek yoghurt, low fat",2,100,"1/3 cup",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Chia seeds",4,10,"2 tsp",null,null],["Honey",5,10,"1 1/2 tsp",null,null]]},{"k":"bal-a-lunch","f":"balanced","d":"A","m":"lunch","n":"Teriyaki chicken rice bowl","ds":"Sticky soy and honey chicken with rice, broccoli and carrot. Great hot or cold from a lunchbox.","pr":10,"ck":20,"st":["Rinse the rice in a sieve under cold water until the water runs mostly clear. Put it in a small saucepan with 140 ml (just over 1/2 cup) of water.","Bring the rice to the boil, then turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Turn the heat off and leave the lid on for 5 more minutes.","While the rice cooks, cut the chicken into bite-sized pieces about 2 cm wide. Peel and finely chop the garlic. Peel the carrot and cut it into thin sticks. Cut the broccoli into small florets.","In a cup, mix the soy sauce, honey and chopped garlic. This is your teriyaki sauce.","Heat the sesame oil in a frying pan over medium-high heat. Add the chicken and cook for 5 to 6 minutes, turning the pieces, until golden on the outside and white all the way through.","Add the carrot and broccoli with 2 tablespoons of water. Cook for 3 minutes, stirring, until the broccoli is bright green and just tender.","Pour in the teriyaki sauce and stir for 1 minute until it bubbles and coats everything.","Spoon the rice into a bowl, add the chicken and vegetables on top and sprinkle with sesame seeds."],"tp":"Cut into the thickest piece of chicken to check it is cooked: no pink inside.","dt":["dairyfree"],"c":543,"p":45.1,"cb":65.4,"ft":9,"ps":1,"i":[["Chicken breast",6,150,"1 small breast",null,null],["White rice, uncooked",7,70,"1/3 cup",null,null],["Broccoli",8,100,"1 cup of small florets",null,null],["Carrot",9,60,"1/2 medium carrot",null,null],["Salt-reduced soy sauce",10,15,"3 tsp",null,null],["Honey",5,10,"1 1/2 tsp",null,null],["Garlic",11,5,"1 clove",null,null],["Sesame oil",12,5,"1 tsp",null,null],["Sesame seeds",13,3,"1 tsp",null,null]]},{"k":"bal-a-dinner","f":"balanced","d":"A","m":"dinner","n":"Lean beef spaghetti bolognese","ds":"The family classic, made with lean mince and extra vegetables hidden in the sauce.","pr":10,"ck":25,"st":["Fill a large saucepan with water, add a pinch of salt and put it on to boil for the pasta.","Peel and finely chop the onion and garlic. Grate the carrot and zucchini on the large holes of a grater.","Heat the olive oil in a frying pan over medium heat. Add the onion and cook for 3 minutes until soft.","Add the mince and turn the heat up to medium-high. Break it up with a wooden spoon and cook for 5 minutes until browned all over with no pink left.","Stir in the garlic, carrot and zucchini and cook for 2 minutes.","Pour in the canned tomatoes, add the oregano and 50 ml of water. Season with a pinch of salt and pepper. Bring to a simmer, then turn the heat down to low and cook for 10 to 15 minutes, stirring now and then, until thick.","While the sauce simmers, add the spaghetti to the boiling water and cook for the time on the packet (usually 9 to 11 minutes). Drain.","Put the spaghetti in a bowl, spoon the sauce over and finish with the grated parmesan."],"tp":"The sauce freezes well for up to 3 months. Cook a big batch and freeze it in single serves.","dt":[],"c":654,"p":52.1,"cb":70,"ft":15.4,"ps":2,"i":[["Lean beef mince (5% fat)",14,150,"150 g",null,null],["Spaghetti, dry",15,80,"80 g (a bundle the width of a 20c coin)",null,null],["Canned diced tomatoes",16,200,"1/2 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Carrot",9,50,"1/2 small carrot",null,null],["Zucchini",18,70,"1/3 medium zucchini",null,null],["Garlic",11,6,"1 to 2 cloves",null,null],["Olive oil",19,5,"1 tsp",null,null],["Parmesan, grated",20,10,"1 1/2 tbsp",null,null],["Dried oregano or Italian herbs",21,1,"1 tsp",null,null]]},{"k":"bal-a-snack","f":"balanced","d":"A","m":"snack","n":"Peanut butter and banana toast","ds":"A quick, filling snack before or after training.","pr":3,"ck":2,"st":["Toast the slice of bread until golden.","Spread the peanut butter over the toast while it is still warm so it melts slightly.","Peel the banana and slice half of it into thin rounds.","Lay the banana slices over the peanut butter and sprinkle with a pinch of cinnamon."],"tp":"Wrap the other half of the banana tightly in cling wrap and keep it for tomorrow.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":247,"p":8.6,"cb":29.1,"ft":9.2,"ps":3,"i":[["Wholemeal bread",22,40,"1 slice",null,null],["Peanut butter, no added sugar",23,15,"3 tsp",null,null],["Banana",24,60,"1/2 medium banana",null,null],["Cinnamon",25,0.5,"a pinch",null,null]]},{"k":"bal-b-breakfast","f":"balanced","d":"B","m":"breakfast","n":"Scrambled eggs on toast with spinach and tomatoes","ds":"Soft, creamy scrambled eggs on wholemeal toast with wilted spinach and cherry tomatoes.","pr":5,"ck":8,"st":["Crack the eggs into a bowl, add the milk and a pinch of salt and pepper, and whisk with a fork until no streaks of white are left.","Cut the cherry tomatoes in half. Put the bread in the toaster.","Melt the butter in a non-stick frying pan over medium-low heat. Add the tomatoes and cook for 2 minutes until they start to soften.","Add the spinach and stir for 30 seconds until it wilts. Push the vegetables to one side of the pan.","Pour the eggs into the empty side. Wait 20 seconds, then gently push the eggs from the edge to the middle with a spatula. Keep doing this slowly.","Take the pan off the heat when the eggs are still slightly wet and shiny. They keep cooking for a few seconds off the heat.","Put the toast on a plate, spoon the eggs over and serve the spinach and tomatoes on the side."],"tp":"Low heat is the secret to soft eggs. High heat makes them rubbery.","dt":["vegetarian","pescatarian"],"c":427,"p":28.8,"cb":31.7,"ft":18.9,"ps":4,"i":[["Eggs",26,150,"3 eggs","egg",50],["Wholemeal bread",22,70,"2 slices",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Reduced fat milk",1,20,"1 tbsp",null,null],["Butter",29,5,"1 tsp",null,null]]},{"k":"bal-b-lunch","f":"balanced","d":"B","m":"lunch","n":"Chicken, avocado and salad wrap","ds":"A fresh, crunchy wrap with grilled chicken, avocado, cheese and salad.","pr":10,"ck":10,"st":["Put the chicken breast between two sheets of baking paper and flatten it with a rolling pin or the bottom of a pan until it is an even 1.5 cm thick. This helps it cook evenly.","Rub the chicken with the olive oil and a pinch of salt, pepper and any dried herbs you like.","Heat a frying pan or grill pan over medium-high heat. Cook the chicken for 4 to 5 minutes on each side until golden and cooked through with no pink in the middle. Rest it on a board for 3 minutes, then slice.","While the chicken cooks, slice the tomato and cucumber thinly and shred the lettuce.","Mash the avocado in a small bowl with the lemon juice and a pinch of salt.","Lay the wrap flat. Spread the avocado down the middle, then add lettuce, tomato, cucumber, chicken and cheese.","Add the yoghurt on top as a dressing.","Fold the bottom of the wrap up over the filling, then fold the sides in and roll it up tightly. Cut in half to serve."],"tp":"Taking it to work? Wrap it tightly in baking paper and keep it cold until lunch.","dt":[],"c":497,"p":39.4,"cb":35.6,"ft":20.4,"ps":5,"i":[["Chicken breast",6,120,"1 small breast",null,null],["Wholemeal wrap",30,60,"1 large wrap",null,null],["Avocado",31,40,"1/4 avocado",null,null],["Cos lettuce",32,30,"2 leaves",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Cucumber",34,40,"1/4 cucumber",null,null],["Cheddar, grated",35,15,"2 tbsp",null,null],["Greek yoghurt, low fat",2,30,"1 1/2 tbsp",null,null],["Olive oil",19,3,"a drizzle",null,null],["Lemon juice",36,5,"1 tsp",null,null]]},{"k":"bal-b-dinner","f":"balanced","d":"B","m":"dinner","n":"Beef burrito bowl","ds":"Mexican spiced mince with brown rice, black beans, corn, salad and a cool yoghurt topping.","pr":10,"ck":30,"st":["Rinse the brown rice and put it in a saucepan with 180 ml of water. Bring to the boil, turn the heat to low, put the lid on and cook for 25 minutes until the water is gone. Leave it covered off the heat for 5 minutes.","Meanwhile, heat the oil in a frying pan over medium-high heat. Add the mince and break it up with a wooden spoon. Cook for 5 minutes until browned with no pink left.","Sprinkle in the spice mix and 3 tablespoons of water. Stir and cook for 2 minutes until the mince is coated and saucy.","Tip the black beans and corn into a sieve, rinse under the tap and drain. Warm them in the pan with the mince for 2 minutes.","Dice the capsicum and tomato into small cubes. Shred the lettuce.","Put the rice in a bowl. Arrange the mince, beans and corn, capsicum, tomato and lettuce on top in sections.","Finish with the cheese and a spoonful of yoghurt, and squeeze the lime over everything."],"tp":"Use microwave brown rice pouches on busy nights. Use 150 g of cooked rice per serve.","dt":[],"c":697,"p":50.8,"cb":75.8,"ft":17.5,"ps":6,"i":[["Lean beef mince (5% fat)",14,130,"130 g",null,null],["Brown rice, uncooked",37,60,"1/4 cup plus 1 tbsp",null,null],["Canned black beans, drained",38,70,"1/3 cup",null,null],["Canned corn kernels, drained",39,50,"1/4 cup",null,null],["Red capsicum",40,60,"1/2 small capsicum",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Cos lettuce",32,30,"2 leaves",null,null],["Cheddar, grated",35,15,"2 tbsp",null,null],["Greek yoghurt, low fat",2,40,"2 tbsp",null,null],["Taco or Mexican spice mix",41,6,"2 tsp",null,null],["Olive oil",19,3,"a drizzle",null,null],["Lime",42,10,"1 wedge",null,null]]},{"k":"bal-b-snack","f":"balanced","d":"B","m":"snack","n":"Greek yoghurt with honey and walnuts","ds":"Thick yoghurt, a drizzle of honey and crunchy walnuts. High protein and ready in a minute.","pr":2,"ck":0,"st":["Spoon the yoghurt into a bowl.","Roughly break the walnuts into smaller pieces with your fingers and scatter them over the yoghurt.","Drizzle the honey over the top and eat straight away so the walnuts stay crunchy."],"tp":"Pack the walnuts in a separate container if you are taking it to work.","dt":["vegetarian","pescatarian","glutenfree"],"c":285,"p":15,"cb":21.8,"ft":14,"ps":7,"i":[["Greek yoghurt, low fat",2,170,"2/3 cup",null,null],["Walnuts",43,15,"5 walnut halves",null,null],["Honey",5,10,"1 1/2 tsp",null,null]]},{"k":"bal-c-breakfast","f":"balanced","d":"C","m":"breakfast","n":"Banana pancakes with yoghurt","ds":"Fluffy Sunday pancakes with banana in the batter, served with Greek yoghurt and maple syrup.","pr":10,"ck":10,"st":["Mash half the banana in a mixing bowl with a fork until smooth. Slice the rest for the top.","Add the egg and milk to the mashed banana and whisk together.","Add the flour and stir with a spoon until just combined. A few small lumps are fine. Do not over-mix or the pancakes go tough.","Heat a non-stick frying pan over medium heat and add a little of the butter. When it sizzles, pour in about 3 tablespoons of batter per pancake. You should get 4 to 5 small pancakes.","Cook until bubbles pop on the top and the edges look dry, about 2 minutes. Flip and cook the other side for 1 minute until golden. Add a little more butter between batches.","Stack the pancakes on a plate. Top with the yoghurt, the sliced banana and a drizzle of maple syrup."],"tp":"If the first pancake is too dark, turn the heat down a little. The first one is always the test.","dt":["vegetarian","pescatarian"],"c":540,"p":24.2,"cb":79.8,"ft":11.9,"ps":8,"i":[["Self-raising flour",44,60,"1/3 cup plus 1 tbsp",null,null],["Egg",26,50,"1 egg","egg",50],["Reduced fat milk",1,100,"1/3 cup plus 1 tbsp",null,null],["Banana",24,80,"2/3 banana",null,null],["Greek yoghurt, low fat",2,100,"1/3 cup",null,null],["Maple syrup",45,10,"1 1/2 tsp",null,null],["Butter",29,4,"1 tsp",null,null]]},{"k":"bal-c-lunch","f":"balanced","d":"C","m":"lunch","n":"Ham, cheese and tomato toastie with side salad","ds":"A golden toasted sandwich with a crisp side salad. Proper Sunday lunch comfort.","pr":5,"ck":6,"st":["Slice the tomato into thin rounds.","Lay one slice of bread flat. Top with the cheese, ham and tomato, then the second slice of bread.","Heat a frying pan over medium heat, or use a sandwich press. Cook the sandwich for 2 to 3 minutes each side, pressing down with a spatula, until golden and the cheese has melted. No butter needed in a non-stick pan.","While it cooks, slice the cucumber and put it in a bowl with the salad leaves.","Whisk the olive oil, balsamic and a pinch of salt and pepper in a cup and toss it through the salad.","Cut the toastie in half and serve with the salad."],"tp":"Let it sit for a minute before cutting so the cheese does not run out.","dt":[],"c":426,"p":26,"cb":36.7,"ft":16.8,"ps":9,"i":[["Wholemeal bread",22,80,"2 slices",null,null],["Lean leg ham",46,60,"3 slices",null,null],["Cheddar, sliced",35,25,"1 thick slice",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Mixed salad leaves",47,40,"1 large handful",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Olive oil",19,5,"1 tsp",null,null],["Balsamic vinegar",48,5,"1 tsp",null,null]]},{"k":"bal-c-dinner","f":"balanced","d":"C","m":"dinner","n":"Sunday roast chicken thighs with vegetables","ds":"Crispy herb chicken thighs roasted on one tray with potato, pumpkin and green beans.","pr":15,"ck":40,"st":["Heat the oven to 200°C (180°C fan). Line a large tray with baking paper.","Peel the potato and cut it into 3 cm chunks. Peel the pumpkin and cut it into chunks the same size. Smaller pieces cook faster.","Put the potato and pumpkin on the tray, drizzle with half the oil, sprinkle with half the rosemary, salt and pepper, and toss with your hands. Roast for 15 minutes.","Meanwhile, rub the chicken thighs with the remaining oil, rosemary, crushed garlic, lemon juice, salt and pepper.","Take the tray out, turn the vegetables over and push them to the sides. Put the chicken in the middle. Roast for another 20 to 25 minutes.","In the last 8 minutes, add the green beans to the tray.","The chicken is ready when the juices run clear when you cut into the thickest part. The vegetables should be golden and soft when pierced with a knife.","Rest the chicken for 3 minutes, then serve with the vegetables and any juices from the tray poured over."],"tp":"Roast extra chicken and vegetables. They make an easy lunch the next day.","dt":["glutenfree","dairyfree"],"c":454,"p":41.2,"cb":34.5,"ft":14.4,"ps":10,"i":[["Chicken thigh fillets, skinless",49,170,"2 small fillets",null,null],["Potato",50,180,"1 medium potato",null,null],["Pumpkin",51,150,"1 large wedge",null,null],["Green beans",52,80,"1 handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh or dried rosemary",53,1,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"bal-c-snack","f":"balanced","d":"C","m":"snack","n":"Banana peanut butter smoothie","ds":"A thick, creamy smoothie that tastes like a milkshake.","pr":5,"ck":0,"st":["Peel the banana and break it into chunks. For an extra thick smoothie, use a banana you froze earlier.","Put the milk, banana, peanut butter, cocoa and ice into a blender.","Blend on high for 30 to 45 seconds until completely smooth and frothy.","Pour into a tall glass and drink straight away."],"tp":"Freeze peeled, overripe bananas in chunks so you always have one ready for smoothies.","dt":["vegetarian","pescatarian","glutenfree"],"c":263,"p":12.9,"cb":29.3,"ft":9.4,"ps":11,"i":[["Reduced fat milk",1,250,"1 cup",null,null],["Banana",24,80,"2/3 banana",null,null],["Peanut butter, no added sugar",23,10,"2 tsp",null,null],["Cocoa powder",54,5,"2 tsp",null,null],["Ice cubes",55,50,"3 ice cubes",null,null]]},{"k":"bud-a-breakfast","f":"budget","d":"A","m":"breakfast","n":"Peanut butter banana porridge","ds":"Hot, creamy porridge in 5 minutes, topped with banana and peanut butter.","pr":2,"ck":5,"st":["Put the oats and milk in a small saucepan, or a large microwave-safe bowl.","Stovetop: cook over medium heat for 4 to 5 minutes, stirring often, until thick and creamy. Microwave: cook on high for 2 minutes, stir, then cook for 1 more minute. Watch it so it does not boil over.","Let it stand for 1 minute to thicken. Add a splash more milk if you like it runnier.","Slice the banana over the top, add the peanut butter and sprinkle with cinnamon."],"tp":"Buy oats and peanut butter in large tubs from the supermarket home brand. It is the cheapest breakfast going.","dt":["vegetarian","pescatarian"],"c":503,"p":20.3,"cb":62.1,"ft":17,"ps":12,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Reduced fat milk",1,250,"1 cup",null,null],["Banana",24,80,"2/3 banana",null,null],["Peanut butter, no added sugar",23,15,"3 tsp",null,null],["Cinnamon",25,0.5,"a pinch",null,null]]},{"k":"bud-a-lunch","f":"budget","d":"A","m":"lunch","n":"Tuna, rice and veggie bowl","ds":"Pantry staples turned into a proper meal: tuna, rice, corn and frozen veg with sweet chilli.","pr":5,"ck":17,"st":["Rinse the rice and put it in a small saucepan with 140 ml of water. Bring to the boil, turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Leave it covered for 5 minutes off the heat.","While the rice cooks, put the frozen vegetables in a microwave-safe bowl with 1 tablespoon of water. Cover and microwave on high for 3 minutes, then drain.","Drain the tuna well and flake it with a fork.","Slice the spring onion thinly.","Put the rice in a bowl, add the vegetables and tuna, drizzle with the soy sauce and sweet chilli sauce, and top with spring onion."],"tp":"Cook a big pot of rice at the start of the week. Cooked rice keeps for 3 days in the fridge. Reheat until steaming hot.","dt":["pescatarian","dairyfree"],"c":488,"p":41.4,"cb":67.5,"ft":4.1,"ps":13,"i":[["Tuna in springwater, drained",56,130,"1 large can (185 g size)",null,null],["White rice, uncooked",7,70,"1/3 cup",null,null],["Frozen mixed vegetables",57,120,"1 cup",null,null],["Sweet chilli sauce",58,15,"2 tsp",null,null],["Salt-reduced soy sauce",10,10,"2 tsp",null,null],["Spring onion",59,10,"1 stem",null,null]]},{"k":"bud-a-dinner","f":"budget","d":"A","m":"dinner","n":"Beef and bean chilli with rice","ds":"A big-batch chilli that stretches lean mince with kidney beans. Cheap, filling and freezes well.","pr":10,"ck":25,"st":["Start the rice: rinse it and put it in a saucepan with 120 ml of water. Bring to the boil, turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Leave it covered off the heat.","Peel and dice the onion. Heat the oil in a frying pan over medium heat and cook the onion for 3 minutes until soft.","Add the mince, turn the heat up and break it up with a spoon. Cook for 5 minutes until browned.","Stir in the chilli powder and cumin and cook for 30 seconds until it smells toasty.","Add the tomatoes, the drained kidney beans and 50 ml of water. Season with salt and pepper. Simmer on low for 12 to 15 minutes until thick.","Serve the chilli over the rice with a spoonful of yoghurt on top."],"tp":"Not a fan of heat? Leave out the chilli powder and use smoked paprika instead.","dt":["glutenfree"],"c":569,"p":42.3,"cb":68.4,"ft":10.4,"ps":14,"i":[["Lean beef mince (5% fat)",14,120,"120 g",null,null],["Canned red kidney beans, drained",60,100,"1/2 cup",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["White rice, uncooked",7,60,"1/4 cup plus 1 tbsp",null,null],["Natural yoghurt",61,30,"1 heaped tbsp",null,null],["Chilli powder",62,1,"1/2 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,3,"a drizzle",null,null]]},{"k":"bud-a-snack","f":"budget","d":"A","m":"snack","n":"Cheese, crackers and an apple","ds":"The no-cook lunchbox snack: crackers, cheddar and a crunchy apple.","pr":3,"ck":0,"st":["Slice the cheese into thin pieces that fit on the crackers.","Wash the apple and cut it into wedges, removing the core.","Top each cracker with cheese and eat with the apple on the side."],"tp":"Squeeze a little lemon juice over the apple wedges to stop them going brown in a lunchbox.","dt":["vegetarian","pescatarian"],"c":252,"p":10.1,"cb":32.4,"ft":7.9,"ps":15,"i":[["Wholegrain crackers",64,25,"4 crackers",null,null],["Cheddar, reduced fat",65,25,"1 thick slice",null,null],["Apple",66,130,"1 medium apple",null,null]]},{"k":"bud-b-breakfast","f":"budget","d":"B","m":"breakfast","n":"Baked beans and eggs on toast","ds":"The cheapest high-protein breakfast there is. Warm beans, eggs and toast in 8 minutes.","pr":2,"ck":8,"st":["Put the baked beans in a small saucepan over low heat, or in a microwave-safe bowl covered with a plate (microwave for 90 seconds, stir halfway).","Put the bread in the toaster.","Spray a non-stick frying pan with oil and heat it over medium heat. Crack in the eggs and cook for 3 minutes for a runny yolk, or 4 to 5 minutes for a firm yolk. Put a lid on the pan to cook the tops.","Put the toast on a plate, spoon the hot beans over and top with the eggs. Season with pepper."],"tp":"Pick the salt-reduced baked beans. They taste the same and have less salt.","dt":["vegetarian","pescatarian","dairyfree"],"c":448,"p":27.1,"cb":47.2,"ft":12.8,"ps":16,"i":[["Baked beans in tomato sauce",67,150,"about 1/3 of a 420 g can",null,null],["Eggs",26,100,"2 eggs","egg",50],["Wholemeal bread",22,70,"2 slices",null,null],["Olive oil spray",19,2,"a quick spray",null,null]]},{"k":"bud-b-lunch","f":"budget","d":"B","m":"lunch","n":"Chicken, pea and corn pasta salad","ds":"A creamy pasta salad you can make the night before and eat cold.","pr":10,"ck":12,"st":["Boil a saucepan of salted water and cook the pasta for the time on the packet. In the last 2 minutes, add the frozen peas to the same pot.","Drain the pasta and peas and rinse under cold water until cool. Shake off as much water as you can.","Shred the cooked chicken with two forks. A supermarket roast chicken or leftover chicken is perfect, just take off the skin.","In a large bowl, stir together the mayonnaise, yoghurt, a pinch of salt and plenty of pepper.","Add the pasta, peas, drained corn, chicken and sliced spring onion and stir until everything is coated.","Eat straight away or keep in the fridge for up to 2 days."],"tp":"The meat from a whole supermarket roast chicken makes about 5 serves of this salad.","dt":[],"c":527,"p":44.6,"cb":64.2,"ft":8.3,"ps":17,"i":[["Pasta shapes, dry",15,70,"3/4 cup",null,null],["Cooked chicken breast",68,100,"3/4 cup shredded",null,null],["Frozen peas",69,50,"1/3 cup",null,null],["Canned corn kernels, drained",39,40,"1/4 cup",null,null],["Light mayonnaise",70,15,"3 tsp",null,null],["Natural yoghurt",61,30,"1 heaped tbsp",null,null],["Spring onion",59,10,"1 stem",null,null]]},{"k":"bud-b-dinner","f":"budget","d":"B","m":"dinner","n":"Sausage and vegetable tray bake","ds":"Lean sausages roasted on one tray with potato, capsicum and onion. Minimal washing up.","pr":10,"ck":35,"st":["Heat the oven to 200°C (180°C fan) and line a tray with baking paper.","Scrub the potato (no need to peel) and cut it into 3 cm chunks. Cut the capsicum into strips and the onion into wedges.","Put the potato on the tray, drizzle with the oil, sprinkle with the herbs, salt and pepper, and toss. Roast for 10 minutes.","Add the sausages, capsicum and onion to the tray. Roast for 20 to 25 minutes, turning the sausages halfway, until browned and cooked through.","In the last 8 minutes, add the frozen green beans to the tray.","Check a sausage is cooked by cutting one in half: no pink inside. Serve everything straight from the tray."],"tp":"Prick the sausages once or twice with a fork before roasting so they do not split.","dt":["dairyfree"],"c":437,"p":25.9,"cb":39.4,"ft":16.8,"ps":18,"i":[["Lean beef sausages",71,140,"2 thick sausages",null,null],["Potato",72,200,"1 large potato",null,null],["Red capsicum",40,80,"1/2 capsicum",null,null],["Red onion",73,60,"1/2 onion",null,null],["Frozen green beans",74,80,"2/3 cup",null,null],["Olive oil",19,5,"1 tsp",null,null],["Dried mixed herbs",75,1,"1 tsp",null,null]]},{"k":"bud-b-snack","f":"budget","d":"B","m":"snack","n":"Yoghurt and muesli cup","ds":"Creamy yoghurt with crunchy muesli. Assemble in a cup and go.","pr":2,"ck":0,"st":["Spoon the yoghurt into a cup or small container.","Sprinkle the muesli and sultanas over the top.","Eat straight away for crunch, or leave in the fridge overnight for a softer, bircher-style snack."],"tp":"Buy a 1 kg tub of yoghurt instead of single tubs. It costs much less per serve.","dt":["vegetarian","pescatarian"],"c":230,"p":13.9,"cb":32.8,"ft":3.4,"ps":19,"i":[["Natural yoghurt, low fat",76,150,"2/3 cup",null,null],["Untoasted muesli",77,30,"1/3 cup",null,null],["Sultanas",78,10,"1 tbsp",null,null]]},{"k":"bud-c-breakfast","f":"budget","d":"C","m":"breakfast","n":"Cheesy omelette with toast","ds":"A fluffy three egg omelette with cheese, tomato and spinach.","pr":5,"ck":6,"st":["Crack the eggs into a bowl, add a pinch of salt and pepper and whisk until smooth.","Dice the tomato. Put the bread in the toaster.","Spray a non-stick frying pan with oil and heat over medium heat. Pour in the eggs and tilt the pan so they cover the base.","Cook for about 1 minute until the edges start to set. Use a spatula to pull the set edges into the middle and let the runny egg flow underneath.","When the top is almost set but still slightly wet, scatter the cheese, tomato and spinach over one half.","Fold the empty half over the filling. Cook for 30 seconds more so the cheese melts, then slide onto a plate with the toast."],"tp":"Use whatever leftover vegetables are in the fridge. Mushrooms, capsicum and onion all work.","dt":["vegetarian","pescatarian"],"c":384,"p":29.9,"cb":18,"ft":20.5,"ps":20,"i":[["Eggs",26,150,"3 eggs","egg",50],["Cheddar, reduced fat, grated",65,20,"1/4 cup",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Baby spinach",27,30,"1 handful",null,null],["Wholemeal bread",22,40,"1 slice",null,null],["Olive oil spray",19,2,"a quick spray",null,null]]},{"k":"bud-c-lunch","f":"budget","d":"C","m":"lunch","n":"Ham and pineapple pita pizza","ds":"Pizza in 10 minutes using a pita bread as the base.","pr":5,"ck":10,"st":["Heat the oven to 220°C (200°C fan) and line a tray with baking paper.","Put the pita on the tray and spread the tomato paste over it, leaving a 1 cm border.","Slice the mushrooms and capsicum thinly. Tear the ham into pieces.","Scatter half the cheese over the base, then the ham, pineapple, mushroom and capsicum, then the rest of the cheese.","Sprinkle with oregano and bake for 8 to 10 minutes until the cheese is bubbling and the edges are crisp.","Let it cool for 1 minute, then cut into quarters."],"tp":"Put the pita straight on the oven rack for the last 2 minutes for an extra crispy base.","dt":[],"c":377,"p":23.2,"cb":42.6,"ft":9.9,"ps":21,"i":[["Wholemeal pita bread",79,70,"1 large pita",null,null],["Tomato paste",80,20,"1 tbsp",null,null],["Lean leg ham",46,50,"2 to 3 slices",null,null],["Mozzarella, grated",81,30,"1/3 cup",null,null],["Pineapple pieces, drained",82,40,"1/4 cup",null,null],["Mushrooms",83,40,"2 mushrooms",null,null],["Red capsicum",40,40,"1/4 capsicum",null,null],["Dried oregano",21,0.5,"a pinch",null,null]]},{"k":"bud-c-dinner","f":"budget","d":"C","m":"dinner","n":"Honey garlic chicken thighs with rice and veg","ds":"Sticky, sweet and savoury chicken thighs in one pan with rice and frozen vegetables.","pr":5,"ck":20,"st":["Rinse the rice and put it in a saucepan with 140 ml of water. Bring to the boil, turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Leave covered off the heat.","Crush or finely chop the garlic. In a cup, mix the honey, soy sauce, garlic and 2 tablespoons of water.","Heat the oil in a frying pan over medium-high heat. Add the chicken thighs and cook for 5 minutes each side until golden.","Turn the heat down to medium and pour in the honey garlic sauce. Let it bubble for 2 to 3 minutes, turning the chicken, until the sauce is sticky and the chicken is cooked through.","Microwave the frozen vegetables in a covered bowl with 1 tablespoon of water for 3 minutes. Drain.","Serve the chicken on the rice with the vegetables, and spoon the sauce from the pan over the top."],"tp":"Thigh fillets are cheaper than breast and stay juicy, so they are hard to overcook.","dt":["dairyfree"],"c":518,"p":36.6,"cb":68,"ft":9.4,"ps":22,"i":[["Chicken thigh fillets, skinless",49,150,"2 small fillets",null,null],["White rice, uncooked",7,70,"1/3 cup",null,null],["Frozen mixed vegetables",57,120,"1 cup",null,null],["Honey",5,12,"2 tsp",null,null],["Salt-reduced soy sauce",10,15,"3 tsp",null,null],["Garlic",11,6,"2 cloves",null,null],["Olive oil",19,4,"1 tsp",null,null]]},{"k":"bud-c-snack","f":"budget","d":"C","m":"snack","n":"Rice cakes with peanut butter, banana and milk","ds":"Crunchy rice cakes with peanut butter and banana, and a glass of cold milk. Two minutes to make.","pr":2,"ck":0,"st":["Spread the peanut butter evenly over the two rice cakes.","Slice the banana and lay the slices on top.","Have it with a glass of cold milk."],"tp":"Eat the rice cakes straight away. They go soft if they sit with the banana on top.","dt":["vegetarian","pescatarian","glutenfree"],"c":314,"p":12.8,"cb":38.2,"ft":11.3,"ps":23,"i":[["Plain rice cakes",84,20,"2 rice cakes",null,null],["Peanut butter, no added sugar",23,15,"3 tsp",null,null],["Banana",24,60,"1/2 banana",null,null],["Reduced fat milk",1,200,"1 glass",null,null]]},{"k":"med-a-breakfast","f":"mediterranean","d":"A","m":"breakfast","n":"Feta, spinach and tomato scrambled eggs on sourdough","ds":"Soft scrambled eggs with salty feta, spinach and cherry tomatoes on toasted sourdough.","pr":5,"ck":8,"st":["Crack the eggs into a bowl with a pinch of pepper (no salt, the feta is salty) and whisk with a fork.","Halve the cherry tomatoes. Put the sourdough in the toaster.","Heat the olive oil in a non-stick frying pan over medium-low heat. Add the tomatoes and cook for 2 minutes, then add the spinach and stir until wilted.","Pour in the eggs. Wait 20 seconds, then slowly push the egg from the edges into the middle with a spatula.","When the eggs are almost set but still a little wet, crumble in the feta and sprinkle the oregano. Stir once and take the pan off the heat.","Spoon onto the toast and serve straight away."],"tp":"Rub a cut garlic clove over the hot toast for extra flavour.","dt":["vegetarian","pescatarian"],"c":446,"p":31.1,"cb":29.1,"ft":21.5,"ps":24,"i":[["Eggs",26,150,"3 eggs","egg",50],["Sourdough bread",85,60,"1 thick slice",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Olive oil",19,5,"1 tsp",null,null],["Dried oregano",21,0.5,"a pinch",null,null]]},{"k":"med-a-lunch","f":"mediterranean","d":"A","m":"lunch","n":"Chicken souvlaki pita with tzatziki","ds":"Lemon and oregano chicken in a warm pita with homemade tzatziki, tomato and onion.","pr":15,"ck":10,"st":["Cut the chicken into 3 cm cubes. In a bowl, mix with the olive oil, half the lemon juice, the oregano and a pinch of salt and pepper. Leave for 5 minutes (or up to a day in the fridge).","Make the tzatziki: grate half the cucumber, squeeze out the water with your hands, and mix it with the yoghurt, the rest of the lemon juice, the garlic (crushed) and a pinch of salt.","Thread the chicken onto skewers if you have them, or cook the pieces loose. Heat a frying pan or grill pan over medium-high heat and cook for 8 to 10 minutes, turning, until charred on the edges and cooked through.","Slice the tomato, the rest of the cucumber and the red onion. Shred the lettuce.","Warm the pita in the dry pan for 30 seconds each side so it is soft and bendy.","Spread the tzatziki over the pita, add the lettuce, tomato, cucumber, onion and chicken, and roll it up. Wrap the bottom in baking paper to hold it together."],"tp":"Soak wooden skewers in water for 30 minutes first so they do not burn.","dt":[],"c":445,"p":42.1,"cb":44.5,"ft":8.9,"ps":25,"i":[["Chicken breast",6,130,"1 small breast",null,null],["Pita bread",87,70,"1 large pita",null,null],["Greek yoghurt, low fat",2,60,"1/4 cup",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Red onion",73,20,"2 thin slices",null,null],["Cos lettuce",32,20,"1 leaf",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Garlic",11,4,"1 small clove",null,null],["Dried oregano",21,1,"1 tsp",null,null]]},{"k":"med-a-dinner","f":"mediterranean","d":"A","m":"dinner","n":"Lamb kofta with tabouli and hummus","ds":"Spiced lamb kofta with a fresh parsley and bulgur tabouli and a spoon of hummus.","pr":20,"ck":12,"st":["Put the fine bulgur in a bowl and pour over 90 ml of boiling water. Cover with a plate and leave for 15 minutes until soft. Fluff with a fork. (Coarse bulgur needs simmering instead: check the packet.)","Finely grate the onion. In another bowl, mix the lamb mince with the grated onion, cumin, coriander, a pinch of salt and pepper. Squish it together with clean hands for 1 minute.","Divide the mince into 4 and shape each piece into a sausage about 10 cm long. Push onto skewers if you like.","Heat a frying pan or grill over medium-high heat with a light brush of the olive oil. Cook the kofta for 8 to 10 minutes, turning every 2 minutes, until browned all over and cooked through.","While they cook, finely chop the parsley, tomato and cucumber. Mix them with the bulgur, the lemon juice, the rest of the olive oil and a pinch of salt. That is your tabouli.","Serve the kofta on the tabouli with the hummus on the side."],"tp":"Wet your hands before shaping the kofta so the mince does not stick.","dt":["dairyfree"],"c":499,"p":35.7,"cb":35.5,"ft":21.3,"ps":26,"i":[["Lean lamb mince",88,130,"130 g",null,null],["Fine bulgur (cracked wheat), dry",89,45,"1/4 cup",null,null],["Flat-leaf parsley",90,25,"1 big handful",null,null],["Tomato",33,80,"1 small tomato",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Brown onion",17,30,"1/4 onion",null,null],["Hummus",91,30,"1 heaped tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,15,"3 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Ground coriander",92,1,"1/2 tsp",null,null]]},{"k":"med-a-snack","f":"mediterranean","d":"A","m":"snack","n":"Hummus with veggie sticks and crackers","ds":"Creamy hummus with crunchy carrot, cucumber and a few wholegrain crackers.","pr":5,"ck":0,"st":["Peel the carrot. Cut the carrot and cucumber into sticks about the length of your finger.","Spoon the hummus into a small bowl or container.","Dip the vegetables and crackers into the hummus."],"tp":"Cut a few days of carrot sticks at once and keep them in a container of water in the fridge so they stay crunchy. Cut the cucumber on the day.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":217,"p":6.2,"cb":20.3,"ft":11,"ps":27,"i":[["Hummus",91,50,"2 heaped tbsp",null,null],["Carrot",9,80,"1 small carrot",null,null],["Cucumber",34,80,"1/2 cucumber",null,null],["Wholegrain crackers",64,15,"2 to 3 crackers",null,null]]},{"k":"med-b-breakfast","f":"mediterranean","d":"B","m":"breakfast","n":"Greek yoghurt bowl with berries, oats and walnuts","ds":"Thick yoghurt topped with toasted oats, berries, walnuts and honey.","pr":5,"ck":3,"st":["Put the oats in a dry frying pan over medium heat. Stir for 2 to 3 minutes until they smell nutty and start to turn golden. Tip them onto a plate to cool.","If the berries are frozen, microwave them for 40 seconds so they are soft and juicy.","Spoon the yoghurt into a bowl.","Top with the toasted oats, berries and broken-up walnuts, then drizzle the honey over."],"tp":"Toast a whole batch of oats at once and keep them in a jar for a week.","dt":["vegetarian","pescatarian"],"c":481,"p":22,"cb":51.1,"ft":18,"ps":28,"i":[["Greek yoghurt, low fat",2,200,"3/4 cup",null,null],["Rolled oats",0,35,"1/3 cup",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Walnuts",43,15,"5 walnut halves",null,null],["Honey",5,10,"1 1/2 tsp",null,null]]},{"k":"med-b-lunch","f":"mediterranean","d":"B","m":"lunch","n":"Greek salad with chicken and quinoa","ds":"A filling Greek salad with grilled chicken, quinoa, olives and feta.","pr":10,"ck":20,"st":["Rinse the quinoa well in a fine sieve (this removes the bitter coating). Put it in a small saucepan with 120 ml of water, bring to the boil, then cover and simmer on low for 12 minutes. Turn off and leave covered for 5 minutes, then fluff with a fork and let it cool.","Season the chicken with salt, pepper and half the oregano. Cook it in a frying pan with a few drops of the oil over medium-high heat for 4 to 5 minutes each side until cooked through. Rest for 3 minutes, then slice.","Cut the cucumber and tomato into chunks and slice the onion thinly.","Whisk the rest of the olive oil with the lemon juice and the remaining oregano.","Put the quinoa in a bowl, add the vegetables and olives, then the chicken. Crumble the feta over and pour on the dressing."],"tp":"Pack the dressing separately if you are making this for work so the salad stays crisp.","dt":["glutenfree"],"c":480,"p":40.9,"cb":31.5,"ft":18.8,"ps":29,"i":[["Chicken breast",6,120,"1 small breast",null,null],["Quinoa, uncooked",93,45,"1/4 cup",null,null],["Cucumber",34,70,"1/2 cucumber",null,null],["Tomato",33,80,"1 small tomato",null,null],["Red onion",73,20,"2 thin slices",null,null],["Kalamata olives",94,20,"5 olives",null,null],["Feta, reduced fat",86,25,"2 tbsp crumbled",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Dried oregano",21,0.5,"a pinch",null,null]]},{"k":"med-b-dinner","f":"mediterranean","d":"B","m":"dinner","n":"Lemon and olive chicken with roast vegetables and couscous","ds":"Chicken thighs roasted with lemon, olives and Mediterranean vegetables, served on fluffy couscous.","pr":10,"ck":30,"st":["Heat the oven to 200°C (180°C fan) and line a tray with baking paper.","Cut the zucchini, capsicum and onion into 3 cm chunks, put them on the tray and toss with half the olive oil.","Rub the chicken with the rest of the oil, the crushed garlic, oregano, half the lemon juice, salt and pepper. Put it on the tray with the vegetables and scatter the olives around.","Roast for 25 to 30 minutes until the chicken is golden and cooked through and the vegetables are soft and charred at the edges.","In the last 10 minutes, put the couscous in a bowl with a pinch of salt and pour over 80 ml of boiling water. Cover with a plate for 5 minutes, then fluff with a fork.","Spoon the couscous onto a plate, top with the vegetables and chicken, and squeeze over the rest of the lemon juice."],"tp":"Use the juices left on the tray as a dressing for the couscous.","dt":["dairyfree"],"c":534,"p":40.2,"cb":53.9,"ft":15.6,"ps":30,"i":[["Chicken thigh fillets, skinless",49,150,"2 small fillets",null,null],["Couscous, dry",95,60,"1/3 cup",null,null],["Zucchini",18,100,"1/2 zucchini",null,null],["Red capsicum",40,80,"1/2 capsicum",null,null],["Red onion",73,50,"1/2 small onion",null,null],["Kalamata olives",94,15,"4 olives",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon",36,15,"juice of 1/2 lemon",null,null],["Garlic",11,6,"2 cloves",null,null],["Dried oregano",21,1,"1 tsp",null,null]]},{"k":"med-b-snack","f":"mediterranean","d":"B","m":"snack","n":"Ricotta and berry toast","ds":"Creamy ricotta on wholegrain toast with berries and a little honey.","pr":3,"ck":2,"st":["Toast the bread.","Microwave the berries for 30 seconds if frozen.","Spread the ricotta thickly over the toast, spoon the berries on top and drizzle with honey."],"tp":"A pinch of lemon zest in the ricotta makes this taste like cheesecake.","dt":["vegetarian","pescatarian"],"c":181,"p":8.7,"cb":25.5,"ft":3.6,"ps":31,"i":[["Wholegrain bread",96,40,"1 slice",null,null],["Ricotta, reduced fat",97,60,"3 tbsp",null,null],["Frozen mixed berries",3,50,"1/3 cup",null,null],["Honey",5,5,"3/4 tsp",null,null]]},{"k":"med-c-breakfast","f":"mediterranean","d":"C","m":"breakfast","n":"Shakshuka with crusty bread","ds":"Eggs gently cooked in a spiced tomato and capsicum sauce, topped with feta. A slow Sunday breakfast.","pr":10,"ck":20,"st":["Dice the onion and capsicum and finely chop the garlic.","Heat the oil in a small frying pan (about 20 cm) over medium heat. Cook the onion and capsicum for 5 minutes until soft.","Add the garlic, cumin and paprika and stir for 30 seconds until fragrant.","Pour in the tomatoes, season with salt and pepper and simmer for 8 minutes until slightly thick.","Use a spoon to make 2 small wells in the sauce. Crack an egg into each well.","Put a lid on the pan (or a plate) and cook on low for 5 to 7 minutes until the whites are set and the yolks are still soft. Check after 5 minutes.","Crumble the feta over the top. Toast the sourdough and use it to scoop up the sauce and eggs."],"tp":"If you like your yolks firm, keep the lid on for 2 more minutes.","dt":["vegetarian","pescatarian"],"c":446,"p":27,"cb":39.1,"ft":18,"ps":32,"i":[["Eggs",26,100,"2 eggs","egg",50],["Canned diced tomatoes",16,200,"1/2 can",null,null],["Red capsicum",40,70,"1/2 small capsicum",null,null],["Brown onion",17,50,"1/2 small onion",null,null],["Garlic",11,6,"2 cloves",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Sourdough bread",85,60,"1 thick slice",null,null],["Olive oil",19,5,"1 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"med-c-lunch","f":"mediterranean","d":"C","m":"lunch","n":"Tuna, white bean and rocket salad","ds":"A Tuscan-style salad of tuna, cannellini beans, rocket and tomatoes with crusty bread.","pr":10,"ck":0,"st":["Rinse the cannellini beans in a sieve under cold water and drain well.","Halve the cherry tomatoes, slice the onion as thin as you can and roughly chop the parsley.","In a large bowl, whisk the olive oil, lemon juice and a pinch of salt and pepper.","Add the beans, tomatoes, onion and parsley and toss through the dressing.","Drain the tuna and break it into chunks over the salad. Add the rocket and toss gently.","Serve with the sourdough, toasted if you like."],"tp":"Let the beans sit in the dressing for 10 minutes before adding the rocket. They soak up the flavour.","dt":["pescatarian","dairyfree"],"c":476,"p":47.3,"cb":36.1,"ft":11.9,"ps":33,"i":[["Tuna in springwater, drained",56,130,"1 large can (185 g size)",null,null],["Canned cannellini beans, drained",99,120,"1/2 can",null,null],["Rocket",100,40,"2 handfuls",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Red onion",73,20,"2 thin slices",null,null],["Flat-leaf parsley",90,5,"a few sprigs",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Sourdough bread",85,40,"1 small slice",null,null]]},{"k":"med-c-dinner","f":"mediterranean","d":"C","m":"dinner","n":"Beef souvlaki skewers with Greek salad and rice","ds":"Marinated beef and vegetable skewers with brown rice and a fresh Greek salad.","pr":20,"ck":30,"st":["Rinse the brown rice and put it in a saucepan with 180 ml of water. Bring to the boil, cover and simmer on low for 25 minutes. Leave covered off the heat for 5 minutes.","Trim any fat off the steak and cut it into 3 cm cubes. Mix with half the olive oil, half the lemon juice, the crushed garlic, oregano, salt and pepper. Leave for at least 10 minutes.","Cut the capsicum, zucchini and half the onion into 3 cm pieces.","Thread the beef and vegetables onto skewers, alternating them.","Cook on a hot grill pan or barbecue over high heat for 8 to 10 minutes, turning every 2 minutes, until the beef is browned outside and still a little pink inside (or longer if you like it well done).","For the salad, chop the cucumber and tomato into chunks, slice the rest of the onion thinly, and toss with the remaining oil and lemon juice. Crumble the feta over.","Serve the skewers on the rice with the salad on the side."],"tp":"Rest the skewers for 2 minutes before eating so the beef stays juicy.","dt":["glutenfree"],"c":550,"p":43.2,"cb":52.1,"ft":16.4,"ps":34,"i":[["Beef rump steak, lean",101,150,"150 g",null,null],["Brown rice, uncooked",37,60,"1/4 cup plus 1 tbsp",null,null],["Red capsicum",40,60,"1/2 small capsicum",null,null],["Zucchini",18,60,"1/3 zucchini",null,null],["Red onion",73,40,"1/3 onion",null,null],["Cucumber",34,60,"1/2 cucumber",null,null],["Tomato",33,80,"1 small tomato",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,15,"3 tsp",null,null],["Garlic",11,4,"1 clove",null,null],["Dried oregano",21,1,"1 tsp",null,null]]},{"k":"med-c-snack","f":"mediterranean","d":"C","m":"snack","n":"Greek yoghurt with honey and pistachios","ds":"Thick yoghurt with a drizzle of honey and crunchy pistachios.","pr":2,"ck":0,"st":["Spoon the yoghurt into a bowl.","Roughly chop the pistachios.","Scatter the pistachios over the yoghurt and drizzle with the honey."],"tp":"Add a pinch of cinnamon for a baklava-style flavour.","dt":["vegetarian","pescatarian","glutenfree"],"c":239,"p":13.9,"cb":19.5,"ft":10.5,"ps":35,"i":[["Greek yoghurt, low fat",2,150,"2/3 cup",null,null],["Pistachios, shelled",102,15,"1 small handful",null,null],["Honey",5,8,"1 tsp",null,null]]},{"k":"veg-a-breakfast","f":"vegetarian","d":"A","m":"breakfast","n":"Spinach, mushroom and feta omelette","ds":"A fluffy omelette packed with mushrooms, spinach and feta, with a slice of toast.","pr":5,"ck":8,"st":["Slice the mushrooms thinly. Whisk the eggs in a bowl with a pinch of pepper (no salt, the feta is salty). Put the bread in the toaster.","Heat half the oil in a non-stick frying pan over medium heat. Cook the mushrooms for 3 minutes until golden, add the spinach and stir until wilted. Tip them onto a plate.","Add the rest of the oil to the pan and pour in the eggs. Tilt the pan so the egg covers the base.","As the edges set, pull them into the middle with a spatula and let the runny egg flow to the edges. Cook for about 2 minutes.","When the top is nearly set, spoon the mushrooms and spinach over one half and crumble on the feta.","Fold the omelette in half, cook for 30 seconds more and slide it onto a plate. Serve with the toast."],"tp":"Wipe mushrooms with a damp paper towel instead of washing them. They stay firm and brown better.","dt":["vegetarian","pescatarian"],"c":399,"p":30.7,"cb":16.9,"ft":22,"ps":36,"i":[["Eggs",26,150,"3 eggs","egg",50],["Mushrooms",83,60,"3 mushrooms",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Wholegrain bread",96,40,"1 slice",null,null],["Olive oil",19,4,"1 tsp",null,null]]},{"k":"veg-a-lunch","f":"vegetarian","d":"A","m":"lunch","n":"Black bean and cheese quesadilla with salad","ds":"Crispy tortillas filled with spiced black beans, corn and melted cheese.","pr":10,"ck":8,"st":["Rinse and drain the black beans. Put them in a bowl with the cumin, paprika and a pinch of salt and mash roughly with a fork, leaving some beans whole.","Dice the capsicum finely and stir it and the corn into the beans.","Lay one wrap flat. Spread the bean mix over it, scatter the cheese on top and put the second wrap on top.","Heat a large dry frying pan over medium heat. Slide the quesadilla into the pan and cook for 2 to 3 minutes until golden underneath. Put a plate on top, flip the pan over so the quesadilla lands on the plate, then slide it back in to cook the other side for 2 minutes.","Cut into 4 wedges like a pizza.","Serve with the salad leaves and chopped tomato on the side and the yoghurt for dipping."],"tp":"Press down on the quesadilla with a spatula while it cooks to help the cheese stick it together.","dt":["vegetarian","pescatarian"],"c":671,"p":35.5,"cb":82.3,"ft":17.5,"ps":37,"i":[["Wholemeal wraps",30,80,"2 small wraps",null,null],["Canned black beans, drained",38,120,"2/3 cup",null,null],["Canned corn kernels, drained",39,40,"1/4 cup",null,null],["Cheddar, reduced fat, grated",65,30,"1/3 cup",null,null],["Red capsicum",40,50,"1/3 capsicum",null,null],["Greek yoghurt, low fat",2,100,"1/3 cup plus 1 tbsp",null,null],["Mixed salad leaves",47,30,"1 handful",null,null],["Tomato",33,50,"1/2 small tomato",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"veg-a-dinner","f":"vegetarian","d":"A","m":"dinner","n":"Chickpea, spinach and paneer curry with rice","ds":"A mild tomato curry with chickpeas, paneer and spinach, made creamy with Greek yoghurt. Ready in 30 minutes.","pr":10,"ck":20,"st":["Rinse the rice and put it in a saucepan with 120 ml of water. Bring to the boil, cover and cook on the lowest heat for 12 minutes. Leave covered off the heat.","Dice the onion. Finely chop the garlic. Peel the ginger with the edge of a teaspoon and grate it. Cut the paneer into 2 cm cubes.","Heat the oil in a deep frying pan over medium heat. Add the paneer and fry for 3 minutes, turning, until golden on a few sides. Lift it out onto a plate.","In the same pan, cook the onion for 4 minutes until soft. Add the garlic, ginger and curry powder and stir for 1 minute.","Add the tomatoes, the drained chickpeas and 60 ml of water. Simmer for 10 minutes, stirring now and then.","Stir in the spinach until wilted, then add the paneer back in and warm through for 1 minute. Take the pan off the heat and stir in the yoghurt (off the heat so it does not split). Taste and add a pinch of salt if needed.","Serve the curry over the rice."],"tp":"No paneer? Use firm tofu or halloumi instead.","dt":["vegetarian","pescatarian","glutenfree"],"c":769,"p":33.6,"cb":78.3,"ft":30.6,"ps":38,"i":[["Paneer",103,80,"80 g",null,null],["Canned chickpeas, drained",104,120,"2/3 cup",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Greek yoghurt, low fat",2,80,"1/3 cup",null,null],["Baby spinach",27,50,"2 handfuls",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh ginger",105,5,"2 cm piece",null,null],["Mild curry powder",106,4,"2 tsp",null,null],["Basmati rice, uncooked",7,60,"1/4 cup plus 1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null]]},{"k":"veg-a-snack","f":"vegetarian","d":"A","m":"snack","n":"Cottage cheese, crackers and tomato","ds":"Cottage cheese piled on crackers with sliced tomato and cracked pepper.","pr":3,"ck":0,"st":["Halve the cherry tomatoes.","Spread the cottage cheese over the crackers.","Top with the tomatoes and a good grind of black pepper."],"tp":"A pinch of dried chilli flakes or everything bagel seasoning on top is great here.","dt":["vegetarian","pescatarian"],"c":236,"p":21.6,"cb":20.9,"ft":5.4,"ps":39,"i":[["Cottage cheese, reduced fat",107,150,"2/3 cup",null,null],["Wholegrain crackers",64,20,"3 crackers",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null]]},{"k":"veg-b-breakfast","f":"vegetarian","d":"B","m":"breakfast","n":"Peanut butter protein overnight oats","ds":"Overnight oats with Greek yoghurt, whey protein, peanut butter and banana.","pr":5,"ck":0,"st":["Put the oats and protein powder in a jar or container that holds at least 600 ml.","Add the milk and stir well until there are no powder lumps and all the oats are wet.","Stir in the yoghurt, peanut butter and cinnamon until smooth. If the peanut butter is stiff, warm it in the microwave for 10 seconds first.","Put the lid on and refrigerate for at least 4 hours or overnight.","In the morning, stir, add a splash of milk if it is too thick, and top with the sliced banana."],"tp":"Slice the banana in the morning, not the night before, or it turns brown.","dt":["vegetarian","pescatarian"],"c":627,"p":42.9,"cb":63.6,"ft":19.1,"ps":40,"i":[["Rolled oats",0,50,"1/2 cup",null,null],["Reduced fat milk",1,180,"3/4 cup",null,null],["Greek yoghurt, low fat",2,150,"2/3 cup",null,null],["Peanut butter, no added sugar",23,15,"3 tsp",null,null],["Banana",24,60,"1/2 banana",null,null],["Whey protein powder, vanilla or unflavoured",108,20,"20 g (scoop sizes vary)",null,null],["Cinnamon",25,0.5,"a pinch",null,null]]},{"k":"veg-b-lunch","f":"vegetarian","d":"B","m":"lunch","n":"Poached egg and avocado smash on sourdough","ds":"The cafe favourite at home: lemony smashed avocado, feta and poached eggs on sourdough.","pr":5,"ck":8,"st":["Fill a saucepan with water about 8 cm deep and bring to a gentle simmer: small bubbles on the bottom, not a rolling boil. Add the vinegar.","Crack each egg into its own cup. Stir the water in a circle to make a gentle whirlpool, then tip one egg into the middle. Add the other eggs next to it, one at a time.","Cook for 3 minutes for runny yolks. Lift the eggs out with a slotted spoon and rest them on paper towel.","While the eggs cook, toast the sourdough. Mash the avocado with the lemon juice, salt and pepper.","Spread the avocado on the toast, top with rocket, the poached eggs (any extra on the side) and crumbled feta. Add chilli flakes if you like heat."],"tp":"Use the freshest eggs you have. Fresh eggs hold together much better when poaching.","dt":["vegetarian","pescatarian"],"c":473,"p":30.4,"cb":31.7,"ft":23.4,"ps":41,"i":[["Eggs",26,150,"3 eggs","egg",50],["Sourdough bread",85,70,"1 large slice",null,null],["Avocado",31,50,"1/3 avocado",null,null],["Feta, reduced fat",86,15,"1 heaped tbsp crumbled",null,null],["Rocket",100,20,"1 handful",null,null],["Lemon juice",36,5,"1 tsp",null,null],["White vinegar",109,5,"1 tsp",null,null]]},{"k":"veg-b-dinner","f":"vegetarian","d":"B","m":"dinner","n":"Lentil bolognese with wholemeal spaghetti","ds":"A rich, meaty-tasting bolognese made with lentils and vegetables.","pr":10,"ck":25,"st":["Put a large saucepan of salted water on to boil for the pasta.","Finely dice the onion, carrot and celery (or blitz them in a food processor). Chop the garlic. Rinse the lentils in a sieve and drain.","Heat the oil in a frying pan over medium heat. Cook the onion, carrot and celery for 6 minutes, stirring, until soft and sweet.","Add the garlic, tomato paste and herbs and stir for 1 minute.","Add the tomatoes, the rinsed lentils and 100 ml of water. Season with salt and pepper. Simmer on low for 15 minutes until thick.","Cook the spaghetti for the time on the packet and drain.","Serve the sauce over the spaghetti with the parmesan on top."],"tp":"Strict vegetarian? Some parmesan is made with animal rennet. Look for one labelled vegetarian.","dt":["vegetarian","pescatarian"],"c":662,"p":34,"cb":88.1,"ft":12.5,"ps":42,"i":[["Canned brown lentils, drained",110,200,"1 cup",null,null],["Wholemeal spaghetti, dry",111,80,"80 g",null,null],["Canned diced tomatoes",16,200,"1/2 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Carrot",9,50,"1/2 small carrot",null,null],["Celery",112,40,"1 stick",null,null],["Garlic",11,6,"2 cloves",null,null],["Tomato paste",80,15,"3 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Parmesan, grated",20,15,"2 tbsp",null,null],["Dried Italian herbs",75,1,"1 tsp",null,null]]},{"k":"veg-b-snack","f":"vegetarian","d":"B","m":"snack","n":"Edamame and a cheese stick","ds":"Salty, steamed edamame beans with a cheese stick. High protein, zero effort.","pr":1,"ck":4,"st":["Put the frozen edamame in a microwave-safe bowl with 1 tablespoon of water.","Cover and microwave on high for 3 minutes, stirring halfway, until hot.","Drain, sprinkle with a pinch of salt and eat with the cheese stick."],"tp":"Find frozen edamame in the frozen vegetable section or at Asian grocers.","dt":["vegetarian","pescatarian","glutenfree"],"c":229,"p":22.4,"cb":11.4,"ft":11.8,"ps":43,"i":[["Frozen shelled edamame",113,150,"1 cup",null,null],["Cheddar cheese stick",65,20,"1 cheese stick",null,null]]},{"k":"veg-c-breakfast","f":"vegetarian","d":"C","m":"breakfast","n":"Ricotta hotcakes with berries","ds":"Light, fluffy hotcakes made with ricotta, topped with warm berries and maple syrup.","pr":10,"ck":10,"st":["Separate the egg: crack it and pass the yolk between the two shell halves, letting the white drop into a clean bowl. Put the yolk in a second bowl.","Add the ricotta and milk to the yolk and whisk until smooth. Stir in the flour until just combined.","Whisk the egg white with a clean whisk for 2 to 3 minutes until it is thick and white and holds soft peaks. Gently fold it into the batter with a spoon. This makes them fluffy.","Heat a non-stick pan over medium-low heat with a little butter. Add 3 tablespoons of batter per hotcake and cook for 2 to 3 minutes until golden underneath, then flip and cook for 2 minutes more.","Warm the berries in the microwave for 40 seconds.","Stack the hotcakes, add a dollop of Greek yoghurt, spoon over the berries and their juice and drizzle with maple syrup."],"tp":"Cook these on lower heat than normal pancakes. The ricotta makes them brown faster.","dt":["vegetarian","pescatarian"],"c":499,"p":26.6,"cb":62.7,"ft":13.6,"ps":44,"i":[["Ricotta, reduced fat",97,100,"1/3 cup plus 1 tbsp",null,null],["Egg",26,50,"1 egg","egg",50],["Self-raising flour",44,50,"1/3 cup",null,null],["Reduced fat milk",1,60,"1/4 cup",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Greek yoghurt, low fat",2,80,"1/3 cup",null,null],["Maple syrup",45,10,"1 1/2 tsp",null,null],["Butter",29,4,"1 tsp",null,null]]},{"k":"veg-c-lunch","f":"vegetarian","d":"C","m":"lunch","n":"Halloumi, pumpkin and quinoa salad","ds":"Golden halloumi with roast pumpkin, quinoa, rocket and pepitas.","pr":10,"ck":25,"st":["Heat the oven to 200°C (180°C fan). Peel the pumpkin and cut it and the zucchini into 2 cm cubes. Toss with half the oil, salt and pepper on a lined tray and roast for 20 to 25 minutes until golden.","Rinse the quinoa, then simmer it in 130 ml of water in a covered saucepan for 12 minutes. Leave covered off the heat for 5 minutes and fluff with a fork.","Toast the pepitas in a dry frying pan over medium heat for 2 minutes until they start to pop. Tip them out.","Slice the halloumi into 1 cm slices. In the same pan over medium-high heat, cook for 1 to 2 minutes each side until golden.","Rinse and drain the chickpeas. Mix the quinoa, chickpeas, pumpkin, zucchini and rocket in a bowl. Whisk the remaining oil with the balsamic and toss it through.","Top with the halloumi and pepitas. Eat while the halloumi is warm."],"tp":"Halloumi goes squeaky and rubbery when it cools, so cook it last.","dt":["vegetarian","pescatarian","glutenfree"],"c":685,"p":33.9,"cb":54.4,"ft":33.3,"ps":45,"i":[["Halloumi",114,70,"3 to 4 slices",null,null],["Quinoa, uncooked",93,50,"1/4 cup",null,null],["Pumpkin",51,150,"1 large wedge",null,null],["Zucchini",18,70,"1/3 zucchini",null,null],["Canned chickpeas, drained",104,80,"1/2 cup",null,null],["Rocket",100,30,"1 large handful",null,null],["Pepitas (pumpkin seeds)",115,10,"1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Balsamic vinegar",48,10,"2 tsp",null,null]]},{"k":"veg-c-dinner","f":"vegetarian","d":"C","m":"dinner","n":"Bean and cheese stuffed sweet potato","ds":"A whole roasted sweet potato loaded with smoky beans, melted cheese and yoghurt.","pr":10,"ck":45,"st":["Heat the oven to 200°C (180°C fan). Scrub the sweet potato and prick it all over with a fork.","Microwave it on high for 6 minutes to speed things up, then put it on a lined tray and bake for 30 to 35 minutes until a knife slides in easily.","While it bakes, dice the onion. Heat the oil in a frying pan over medium heat and cook the onion for 3 minutes.","Add the paprika and cumin, stir for 30 seconds, then add the beans and tomatoes. Simmer for 8 minutes until thick, then stir in the spinach until it wilts.","Cut the sweet potato open lengthways and push the ends together to open it up.","Spoon in the bean mix, top with the cheese and put it back in the oven for 5 minutes until the cheese melts.","Finish with the yoghurt spooned over the top."],"tp":"Short on time? Cook the sweet potato fully in the microwave for 10 to 12 minutes, turning halfway.","dt":["vegetarian","pescatarian","glutenfree"],"c":632,"p":35.6,"cb":72.3,"ft":15.9,"ps":46,"i":[["Sweet potato",116,250,"1 medium sweet potato",null,null],["Canned red kidney beans, drained",60,150,"3/4 cup",null,null],["Canned diced tomatoes",16,100,"1/4 can",null,null],["Brown onion",17,40,"1/3 onion",null,null],["Cheddar, reduced fat, grated",65,30,"1/3 cup",null,null],["Greek yoghurt, low fat",2,150,"2/3 cup",null,null],["Baby spinach",27,30,"1 handful",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,4,"1 tsp",null,null]]},{"k":"veg-c-snack","f":"vegetarian","d":"C","m":"snack","n":"Banana oat smoothie","ds":"A filling smoothie with milk, banana, oats, Greek yoghurt and a scoop of protein.","pr":5,"ck":0,"st":["Put the oats in the blender first and blitz for 10 seconds until they are a fine powder. This stops the smoothie being gritty.","Add the milk, banana, yoghurt, protein powder, honey and ice.","Blend on high for 30 to 45 seconds until smooth.","Pour into a glass and drink straight away."],"tp":"Add a handful of spinach. You will not taste it, and it adds fibre.","dt":["vegetarian","pescatarian"],"c":440,"p":36.8,"cb":51.3,"ft":7.7,"ps":47,"i":[["Reduced fat milk",1,250,"1 cup",null,null],["Banana",24,80,"2/3 banana",null,null],["Rolled oats",0,20,"1/4 cup",null,null],["Greek yoghurt, low fat",2,80,"1/3 cup",null,null],["Whey protein powder, vanilla or unflavoured",108,25,"25 g (scoop sizes vary)",null,null],["Honey",5,5,"3/4 tsp",null,null],["Ice cubes",55,50,"3 ice cubes",null,null]]},{"k":"vgn-a-breakfast","f":"vegan","d":"A","m":"breakfast","n":"Tofu scramble on toast","ds":"Golden, savoury scrambled tofu with spinach and tomatoes. An egg-free take on scrambled eggs.","pr":5,"ck":8,"st":["Drain the tofu and pat it dry with paper towel.","Heat the oil in a non-stick frying pan over medium heat. Crumble the tofu into the pan with your fingers into small, uneven pieces.","Sprinkle in the turmeric, garlic powder, salt and pepper and stir so the tofu turns yellow. Cook for 4 minutes, stirring, until heated through and starting to brown.","Halve the cherry tomatoes and add them with the spinach. Stir for 2 minutes until the spinach wilts.","Add the soy milk and stir for 30 seconds. This makes it creamy, like scrambled eggs.","Toast the bread and pile the scramble on top."],"tp":"A pinch of black salt (kala namak) from an Indian grocer gives it a real egg flavour.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":525,"p":35.7,"cb":32.2,"ft":25.3,"ps":48,"i":[["Firm tofu",117,200,"2/3 block",null,null],["Wholegrain bread",96,70,"2 slices",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Soy milk",118,20,"1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Ground turmeric",119,0.5,"1/4 tsp",null,null],["Garlic powder",120,0.5,"a pinch",null,null]]},{"k":"vgn-a-lunch","f":"vegan","d":"A","m":"lunch","n":"Chickpea, quinoa and roast veg bowl with tahini","ds":"Roasted chickpeas and vegetables on quinoa with a lemony tahini dressing.","pr":10,"ck":25,"st":["Heat the oven to 200°C (180°C fan) and line a tray with baking paper.","Drain and rinse the chickpeas and pat them dry with paper towel. Peel the pumpkin and cut it into 2 cm cubes. Cut the broccoli into small florets. Cover the edamame with boiling water for 3 minutes, then drain.","Toss the chickpeas and pumpkin with the oil, paprika and a pinch of salt on the tray. Roast for 15 minutes, add the broccoli, and roast for 10 minutes more.","Meanwhile rinse the quinoa and simmer it in 130 ml of water, covered, for 12 minutes. Leave covered off the heat for 5 minutes and fluff with a fork.","Whisk the tahini with the lemon juice and 1 to 2 tablespoons of water until smooth and pourable. It will look thick and lumpy at first, keep whisking.","Put the spinach and quinoa in a bowl, top with the roast vegetables, chickpeas and edamame, and drizzle with the tahini dressing."],"tp":"Roast a double batch of chickpeas. They make a crunchy snack on their own.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":619,"p":30.6,"cb":59.9,"ft":23.8,"ps":49,"i":[["Canned chickpeas, drained",104,120,"2/3 cup",null,null],["Quinoa, uncooked",93,50,"1/4 cup",null,null],["Pumpkin",51,120,"1 wedge",null,null],["Broccoli",8,80,"1 cup of small florets",null,null],["Frozen shelled edamame",113,60,"1/3 cup",null,null],["Baby spinach",27,30,"1 handful",null,null],["Tahini",121,15,"3 tsp",null,null],["Lemon juice",36,15,"3 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"vgn-a-dinner","f":"vegan","d":"A","m":"dinner","n":"Tofu satay stir-fry with noodles","ds":"Crispy tofu and crunchy vegetables in a peanut satay sauce over noodles.","pr":10,"ck":15,"st":["Put the noodles in a heatproof bowl and cover with boiling water. Leave for 5 to 8 minutes (check the packet) until soft, then drain and rinse with cold water so they do not stick.","Drain the tofu, press it between paper towels to squeeze out water, and cut it into 2 cm cubes.","Make the satay sauce: whisk the peanut butter, soy sauce, lime juice, grated garlic and ginger with 3 tablespoons of hot water until smooth.","Heat the oil in a wok or large frying pan over medium-high heat. Add the tofu and cook for 5 to 6 minutes, turning, until golden on most sides. Move it to a plate.","Add the broccoli, sliced capsicum and snow peas with 2 tablespoons of water. Stir-fry for 3 minutes until bright and just tender.","Add the noodles, tofu and satay sauce and toss for 1 minute until everything is coated and hot."],"tp":"Leave the tofu alone in the pan for the first 2 minutes. Moving it too early stops it going crispy.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":713,"p":41.6,"cb":54,"ft":33.1,"ps":50,"i":[["Firm tofu",117,200,"2/3 block",null,null],["Rice stick noodles, soaked",122,170,"60 g dry, about 1 1/2 cups once soaked",null,null],["Broccoli",8,80,"1 cup of small florets",null,null],["Red capsicum",40,60,"1/2 small capsicum",null,null],["Snow peas",123,50,"1 handful",null,null],["Peanut butter, no added sugar",23,20,"1 tbsp",null,null],["Salt-reduced soy sauce",10,15,"3 tsp",null,null],["Lime juice",124,10,"juice of 1/2 lime",null,null],["Garlic",11,5,"1 clove",null,null],["Fresh ginger",105,5,"2 cm piece",null,null],["Olive oil",19,5,"1 tsp",null,null]]},{"k":"vgn-a-snack","f":"vegan","d":"A","m":"snack","n":"Trail mix and a protein soy milk","ds":"A handful of nuts, seeds and dried fruit with a glass of soy milk shaken up with plant protein.","pr":2,"ck":0,"st":["Mix the almonds, pepitas and sultanas in a small container.","Put the cold soy milk and protein powder in a shaker or jar with a lid and shake for 20 seconds until smooth.","Eat the trail mix with the protein milk."],"tp":"Choose a soy milk with added calcium to replace the calcium from dairy.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":411,"p":29.4,"cb":25.2,"ft":20.2,"ps":51,"i":[["Almonds",125,15,"12 almonds",null,null],["Pepitas (pumpkin seeds)",115,10,"1 tbsp",null,null],["Sultanas",78,15,"1 tbsp",null,null],["Soy milk",118,250,"1 cup",null,null],["Plant protein powder, unflavoured or vanilla",126,20,"20 g (scoop sizes vary)",null,null]]},{"k":"vgn-b-breakfast","f":"vegan","d":"B","m":"breakfast","n":"Berry chia overnight oats","ds":"Oats soaked in soy milk with chia seeds, plant protein and berries. Make the night before.","pr":5,"ck":0,"st":["Put the oats and chia seeds in a jar that holds at least 600 ml.","Add the protein powder, then pour in the soy milk and maple syrup and stir very well until no powder lumps are left and the chia seeds are not clumped at the bottom.","Tip the frozen berries on top.","Put the lid on and refrigerate overnight, or for at least 4 hours. Give it a stir after the first 10 minutes if you can, to stop the chia clumping.","In the morning, stir and add the peanut butter on top."],"tp":"Keeps for 3 days in the fridge, so make several at once.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":654,"p":40.2,"cb":61.5,"ft":23.6,"ps":52,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Soy milk",118,250,"1 cup",null,null],["Chia seeds",4,15,"1 tbsp",null,null],["Plant protein powder, unflavoured or vanilla",126,25,"25 g (scoop sizes vary)",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Peanut butter, no added sugar",23,10,"2 tsp",null,null],["Maple syrup",45,10,"1 1/2 tsp",null,null]]},{"k":"vgn-b-lunch","f":"vegan","d":"B","m":"lunch","n":"Red lentil and vegetable soup with bread","ds":"A thick, warming soup of red lentils, vegetables and spinach. Freezes well.","pr":10,"ck":25,"st":["Dice the onion, carrot and celery into small pieces. Chop the garlic.","Heat the oil in a saucepan over medium heat. Cook the onion, carrot and celery for 5 minutes until starting to soften.","Add the garlic and cumin and stir for 1 minute.","Rinse the lentils in a sieve. Add them to the pan with the tomatoes and 400 ml of water (or salt-reduced vegetable stock).","Bring to the boil, then simmer on low with the lid partly on for 18 to 20 minutes, stirring now and then, until the lentils are soft and breaking down.","Stir in the spinach until wilted. Season with salt and pepper. Add more water if you like it thinner.","Serve with the bread, toasted if you like."],"tp":"Make 4 serves at once and freeze the rest in single containers.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":555,"p":30.1,"cb":73.9,"ft":9.3,"ps":53,"i":[["Red lentils, dry",127,90,"1/2 cup",null,null],["Carrot",9,60,"1/2 medium carrot",null,null],["Celery",112,40,"1 stick",null,null],["Brown onion",17,50,"1/2 small onion",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Baby spinach",27,30,"1 handful",null,null],["Garlic",11,5,"1 clove",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Wholegrain bread",96,50,"1 large slice",null,null]]},{"k":"vgn-b-dinner","f":"vegan","d":"B","m":"dinner","n":"Black bean, tofu and sweet potato tacos","ds":"Roasted sweet potato, spiced black beans and crumbled tofu in warm tortillas with avocado and crunchy slaw.","pr":15,"ck":25,"st":["Heat the oven to 200°C (180°C fan). Peel the sweet potato and cut it into 1.5 cm cubes. Toss with the oil, half the cumin and paprika, and salt on a lined tray. Roast for 20 to 25 minutes until soft and golden.","Drain the tofu, pat it dry and crumble it into a frying pan over medium-high heat. Cook for 4 minutes, stirring, until it starts to brown.","Rinse the black beans and add them to the tofu with the rest of the cumin and paprika and 2 tablespoons of water. Cook for 3 minutes, lightly mashing some of the beans with a fork.","Shred the cabbage thinly and toss with half the lime juice and a pinch of salt.","Mash the avocado with the rest of the lime juice and a pinch of salt.","Warm the tortillas one at a time in a dry frying pan for 20 seconds each side until soft.","Fill each tortilla with the bean and tofu mix, sweet potato, slaw and avocado, and top with coriander."],"tp":"Wrap warmed tortillas in a clean tea towel to keep them soft while you build the tacos.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":746,"p":33.7,"cb":86.3,"ft":23.2,"ps":54,"i":[["Corn tortillas",128,75,"3 small tortillas",null,null],["Canned black beans, drained",38,150,"3/4 cup",null,null],["Firm tofu",117,100,"1/3 block",null,null],["Sweet potato",116,150,"1/2 medium sweet potato",null,null],["Avocado",31,40,"1/4 avocado",null,null],["Red cabbage",129,40,"1/2 cup shredded",null,null],["Lime juice",124,10,"juice of 1/2 lime",null,null],["Fresh coriander",130,3,"a few sprigs",null,null],["Olive oil",19,5,"1 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"vgn-b-snack","f":"vegan","d":"B","m":"snack","n":"Chilli salt edamame","ds":"Steamed edamame beans tossed with salt and chilli flakes.","pr":1,"ck":4,"st":["Put the frozen edamame in a microwave-safe bowl with 1 tablespoon of water.","Cover and microwave on high for 3 minutes, stirring halfway.","Drain and toss with a pinch of salt and chilli flakes."],"tp":"Edamame is one of the highest-protein plant snacks you can buy.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":220,"p":22.5,"cb":15.3,"ft":9.5,"ps":55,"i":[["Frozen shelled edamame",113,200,"1 1/3 cups",null,null],["Chilli flakes",131,0.5,"a pinch",null,null]]},{"k":"vgn-c-breakfast","f":"vegan","d":"C","m":"breakfast","n":"Banana oat pancakes","ds":"Egg-free, dairy-free pancakes made from oats, banana and plant protein, with peanut butter and berries.","pr":10,"ck":10,"st":["Blend the oats in a blender for 20 seconds until they are like flour.","Add the banana, soy milk, protein powder, baking powder and a pinch of salt and blend until smooth. Leave the batter for 5 minutes to thicken.","Heat a non-stick pan over medium-low heat and spray lightly with oil.","Pour in about 3 tablespoons of batter per pancake. Cook for 2 to 3 minutes until bubbles appear and the edges look set, then flip carefully and cook for 1 to 2 minutes more.","Warm the berries in the microwave for 40 seconds.","Stack the pancakes, spread the peanut butter on top, add the berries and drizzle with maple syrup."],"tp":"These are softer than flour pancakes, so make them small and flip them gently.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":662,"p":37.5,"cb":73.4,"ft":20.6,"ps":56,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Banana",24,100,"1 small banana",null,null],["Soy milk",118,120,"1/2 cup",null,null],["Plant protein powder, unflavoured or vanilla",126,30,"30 g (scoop sizes vary)",null,null],["Baking powder",132,3,"3/4 tsp",null,null],["Peanut butter, no added sugar",23,15,"3 tsp",null,null],["Frozen mixed berries",3,50,"1/3 cup",null,null],["Maple syrup",45,10,"1 1/2 tsp",null,null],["Olive oil spray",19,2,"a quick spray",null,null]]},{"k":"vgn-c-lunch","f":"vegan","d":"C","m":"lunch","n":"Smashed chickpea salad sandwich","ds":"A creamy, crunchy chickpea filling with avocado, celery and lemon on wholegrain bread.","pr":10,"ck":0,"st":["Rinse and drain the chickpeas well. Put them in a bowl and mash with a fork or potato masher until mostly broken up, with a few whole ones left for texture.","Add the avocado and mash it in. This replaces mayonnaise and makes it creamy.","Finely dice the celery and red onion and stir them in with the mustard, lemon juice, salt and plenty of pepper.","Slice the tomato.","Spread the chickpea mix thickly on one slice of bread, top with lettuce and tomato and close the sandwich."],"tp":"The filling keeps for 2 days in the fridge. Make the sandwich fresh so the bread does not go soggy.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":454,"p":19.9,"cb":56.1,"ft":11.8,"ps":57,"i":[["Canned chickpeas, drained",104,150,"1 scant cup",null,null],["Wholegrain bread",96,80,"2 slices",null,null],["Avocado",31,30,"1/5 avocado",null,null],["Celery",112,30,"1/2 stick",null,null],["Red onion",73,15,"1 tbsp diced",null,null],["Dijon mustard",133,5,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Cos lettuce",32,20,"1 leaf",null,null],["Tomato",33,50,"1/2 small tomato",null,null]]},{"k":"vgn-c-dinner","f":"vegan","d":"C","m":"dinner","n":"Red lentil dahl with rice","ds":"A creamy, gently spiced lentil dahl with coconut, tomatoes and spinach. The ultimate comfort food.","pr":10,"ck":30,"st":["Rinse the rice and cook it in 80 ml of water: bring to the boil, cover, and cook on the lowest heat for 12 minutes. Leave covered off the heat.","Dice the onion, chop the garlic and grate the ginger.","Heat the oil in a saucepan over medium heat and cook the onion for 4 minutes until soft. Add the garlic, ginger, curry powder and turmeric and stir for 1 minute.","Rinse the lentils and add them with the tomatoes, coconut milk and 350 ml of water.","Bring to the boil, then simmer on low for 20 minutes, stirring often so the lentils do not stick, until thick and creamy. Add a splash of water if it gets too thick.","Stir in the spinach until wilted and season with salt.","Serve the dahl over the rice."],"tp":"A squeeze of lemon just before serving makes all the spices taste brighter.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":659,"p":33,"cb":89.7,"ft":12.4,"ps":58,"i":[["Red lentils, dry",127,110,"1/2 cup plus 1 tbsp",null,null],["Light coconut milk",134,60,"1/4 cup",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh ginger",105,5,"2 cm piece",null,null],["Baby spinach",27,50,"2 handfuls",null,null],["Basmati rice, uncooked",7,40,"2 1/2 tbsp",null,null],["Mild curry powder",106,3,"1 1/2 tsp",null,null],["Ground turmeric",119,1,"1/2 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null]]},{"k":"vgn-c-snack","f":"vegan","d":"C","m":"snack","n":"Chocolate peanut butter smoothie","ds":"A thick chocolate smoothie with soy milk, banana, peanut butter and plant protein.","pr":5,"ck":0,"st":["Put the soy milk, banana, protein powder, peanut butter, cocoa and ice in a blender.","Blend on high for 30 to 45 seconds until completely smooth.","Pour into a tall glass and drink straight away."],"tp":"Use a frozen banana instead of ice for a thicker, creamier smoothie.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":470,"p":37.4,"cb":33.4,"ft":18.5,"ps":59,"i":[["Soy milk",118,300,"1 1/4 cups",null,null],["Banana",24,80,"2/3 banana",null,null],["Peanut butter, no added sugar",23,15,"3 tsp",null,null],["Plant protein powder, unflavoured or vanilla",126,30,"30 g (scoop sizes vary)",null,null],["Cocoa powder",54,5,"2 tsp",null,null],["Ice cubes",55,50,"3 ice cubes",null,null]]},{"k":"pes-a-breakfast","f":"pescatarian","d":"A","m":"breakfast","n":"Smoked salmon and cream cheese bagel","ds":"A toasted bagel with light cream cheese, smoked salmon, capers and rocket.","pr":5,"ck":2,"st":["Slice the bagel in half and toast it.","Spread the cream cheese over both halves.","Lay the smoked salmon on top, then the onion rings, capers and rocket.","Squeeze over a little lemon juice and finish with black pepper."],"tp":"Keep opened smoked salmon in the fridge and use it within 2 days.","dt":["pescatarian"],"c":405,"p":26.1,"cb":44.5,"ft":12.7,"ps":60,"i":[["Bagel",135,85,"1 bagel",null,null],["Smoked salmon",136,60,"3 slices",null,null],["Light cream cheese",137,25,"1 heaped tbsp",null,null],["Rocket",100,15,"1 small handful",null,null],["Red onion",73,10,"2 thin rings",null,null],["Capers",138,5,"1 tsp",null,null],["Lemon juice",36,5,"a squeeze",null,null]]},{"k":"pes-a-lunch","f":"pescatarian","d":"A","m":"lunch","n":"Prawn and avocado poke bowl","ds":"Garlic prawns on sushi-style rice with edamame, cucumber, carrot and avocado.","pr":15,"ck":20,"st":["Rinse the rice well and cook it in 130 ml of water: bring to the boil, cover and cook on the lowest heat for 12 minutes, then leave covered off the heat for 5 minutes. Stir in the rice vinegar and let it cool slightly.","Microwave the edamame with 1 tablespoon of water, covered, for 2 minutes. Drain.","Peel the carrot and grate it or cut it into thin matchsticks. Slice the cucumber and avocado.","Heat the sesame oil in a frying pan over medium-high heat. Add the prawns and chopped garlic and cook for 1 to 2 minutes each side until the prawns turn pink and curl into a C shape. Do not overcook or they go rubbery.","Put the rice in a bowl and arrange the prawns, edamame, cucumber, carrot and avocado on top in sections.","Drizzle with soy sauce and sprinkle with sesame seeds."],"tp":"Prawns are cooked when they are pink all over and curled into a C. A tight O shape means overcooked.","dt":["pescatarian","dairyfree"],"c":540,"p":40.3,"cb":58.3,"ft":14.6,"ps":61,"i":[["Raw peeled prawns",139,130,"8 to 10 prawns",null,null],["White rice, uncooked",7,65,"1/3 cup",null,null],["Frozen shelled edamame",113,50,"1/3 cup",null,null],["Cucumber",34,60,"1/2 cucumber",null,null],["Carrot",9,50,"1/2 small carrot",null,null],["Avocado",31,40,"1/4 avocado",null,null],["Salt-reduced soy sauce",10,15,"3 tsp",null,null],["Rice vinegar",140,5,"1 tsp",null,null],["Sesame oil",12,3,"1/2 tsp",null,null],["Sesame seeds",13,3,"1 tsp",null,null],["Garlic",11,4,"1 clove",null,null]]},{"k":"pes-a-dinner","f":"pescatarian","d":"A","m":"dinner","n":"Honey soy salmon with rice and greens","ds":"Pan-fried salmon with a sticky honey soy glaze, brown rice and broccolini.","pr":5,"ck":30,"st":["Rinse the brown rice and simmer it in 170 ml of water, covered, for 25 minutes. Leave covered off the heat for 5 minutes.","Mix the soy sauce, honey, grated garlic and grated ginger in a cup.","Pat the salmon dry with paper towel. Heat a non-stick frying pan over medium-high heat. Put the salmon in skin side down and cook for 4 minutes without moving it, until the skin is crisp.","Flip the salmon and cook for 2 minutes. Pour the sauce around it and let it bubble for 1 to 2 minutes, spooning it over the fish, until sticky. The salmon is done when it flakes easily but is still slightly pink in the centre.","While the salmon cooks, steam or microwave the broccolini with 1 tablespoon of water for 2 to 3 minutes until bright green.","Serve the salmon on the rice with the broccolini, pour over the pan sauce and sprinkle with sesame seeds."],"tp":"Turn the heat down if the honey starts to burn. It catches quickly.","dt":["pescatarian","dairyfree"],"c":569,"p":39.4,"cb":48.5,"ft":22.7,"ps":62,"i":[["Salmon fillet, skin on",141,140,"1 fillet",null,null],["Brown rice, uncooked",37,55,"1/4 cup",null,null],["Broccolini",142,100,"about 1/2 bunch (6 stems)",null,null],["Salt-reduced soy sauce",10,15,"3 tsp",null,null],["Honey",5,10,"1 1/2 tsp",null,null],["Garlic",11,4,"1 clove",null,null],["Fresh ginger",105,4,"2 cm piece",null,null],["Sesame seeds",13,3,"1 tsp",null,null]]},{"k":"pes-a-snack","f":"pescatarian","d":"A","m":"snack","n":"Tuna and crackers with cherry tomatoes","ds":"Lemon pepper tuna piled on crackers with cherry tomatoes.","pr":3,"ck":0,"st":["Drain the tuna and mix it with the lemon juice and plenty of black pepper.","Halve the tomatoes.","Pile the tuna onto the crackers and eat with the tomatoes."],"tp":"Flavoured tuna tins are easy, but check the label: some are packed in oil and have twice the calories.","dt":["pescatarian","dairyfree"],"c":184,"p":21.1,"cb":14.7,"ft":3.4,"ps":63,"i":[["Tuna in springwater, drained",56,70,"1 small can (95 g size)",null,null],["Wholegrain crackers",64,20,"3 crackers",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Lemon juice",36,5,"a squeeze",null,null]]},{"k":"pes-b-breakfast","f":"pescatarian","d":"B","m":"breakfast","n":"Berry and banana protein porridge","ds":"Creamy porridge with Greek yoghurt stirred through for extra protein, topped with fruit.","pr":2,"ck":5,"st":["Put the oats and milk in a saucepan over medium heat. Cook for 4 to 5 minutes, stirring often, until thick and creamy. (Or microwave for 2 minutes, stir, then 1 minute more.)","Take it off the heat and stir in the yoghurt. Adding it off the heat keeps it creamy.","Warm the berries in the microwave for 40 seconds.","Spoon the porridge into a bowl and top with the berries and sliced banana."],"tp":"Stirring the yoghurt in at the end adds protein without making the porridge sour.","dt":["vegetarian","pescatarian"],"c":450,"p":21.1,"cb":63,"ft":9.7,"ps":64,"i":[["Rolled oats",0,55,"1/2 cup plus 1 tbsp",null,null],["Reduced fat milk",1,220,"just under 1 cup",null,null],["Greek yoghurt, low fat",2,80,"1/3 cup",null,null],["Frozen mixed berries",3,60,"1/2 cup",null,null],["Banana",24,50,"1/2 small banana",null,null]]},{"k":"pes-b-lunch","f":"pescatarian","d":"B","m":"lunch","n":"Tuna, olive and feta pasta salad","ds":"Wholemeal pasta tossed with tuna, cherry tomatoes, olives, spinach and feta.","pr":10,"ck":12,"st":["Cook the pasta in boiling salted water for the time on the packet. Drain and rinse under cold water until cool.","Halve the tomatoes, dice the cucumber and slice the olives.","Whisk the olive oil and lemon juice with salt and pepper in a large bowl.","Add the pasta, tomatoes, cucumber, olives and spinach and toss through the dressing.","Drain the tuna, flake it over the top and crumble on the feta."],"tp":"Keeps for 2 days in the fridge. Add the spinach just before eating so it stays fresh.","dt":["pescatarian"],"c":546,"p":48.9,"cb":46.3,"ft":15.4,"ps":65,"i":[["Wholemeal pasta, dry",111,70,"3/4 cup",null,null],["Tuna in springwater, drained",56,130,"1 large can (185 g size)",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Baby spinach",27,30,"1 handful",null,null],["Kalamata olives",94,15,"4 olives",null,null],["Feta, reduced fat",86,15,"1 heaped tbsp crumbled",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"pes-b-dinner","f":"pescatarian","d":"B","m":"dinner","n":"Spiced fish tacos with slaw","ds":"Spiced white fish in warm tortillas with crunchy slaw, avocado and a lime yoghurt sauce.","pr":15,"ck":10,"st":["Pat the fish dry with paper towel and cut it into 4 strips. Sprinkle both sides with the paprika, cumin, salt and pepper.","Shred the cabbage thinly and grate the carrot. Toss with half the lime juice and a pinch of salt.","Mix the yoghurt with the rest of the lime juice. This is your sauce.","Heat the oil in a non-stick frying pan over medium-high heat. Cook the fish for 2 to 3 minutes each side until golden and it flakes easily with a fork.","Warm the tortillas in a dry pan for 20 seconds each side.","Fill each tortilla with slaw, fish and sliced avocado, and drizzle with the lime yoghurt."],"tp":"Frozen white fish fillets are much cheaper than fresh and work perfectly here. Thaw in the fridge overnight.","dt":["pescatarian"],"c":485,"p":37.9,"cb":42.5,"ft":15.4,"ps":66,"i":[["White fish fillets (barramundi or basa)",143,150,"1 large fillet",null,null],["Corn tortillas",128,75,"3 small tortillas",null,null],["Red cabbage",129,50,"2/3 cup shredded",null,null],["Carrot",9,40,"1/2 small carrot",null,null],["Avocado",31,30,"1/5 avocado",null,null],["Greek yoghurt, low fat",2,40,"2 tbsp",null,null],["Lime juice",124,15,"juice of 1/2 lime",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null]]},{"k":"pes-b-snack","f":"pescatarian","d":"B","m":"snack","n":"Cottage cheese with pineapple","ds":"Creamy cottage cheese with sweet pineapple. A retro snack packed with protein.","pr":2,"ck":0,"st":["Spoon the cottage cheese into a bowl.","Drain the pineapple and add it on top.","Stir together, or eat as is."],"tp":"Fresh pineapple works too and is even better in summer.","dt":["vegetarian","pescatarian","glutenfree"],"c":159,"p":15,"cb":15.9,"ft":3,"ps":67,"i":[["Cottage cheese, reduced fat",107,120,"1/2 cup",null,null],["Pineapple pieces, drained",82,100,"2/3 cup",null,null]]},{"k":"pes-c-breakfast","f":"pescatarian","d":"C","m":"breakfast","n":"Smoked salmon scrambled eggs on sourdough","ds":"Soft scrambled eggs with smoked salmon and chives on toasted sourdough.","pr":5,"ck":6,"st":["Whisk the eggs with pepper (no salt, the salmon is salty). Chop the chives. Tear the salmon into strips.","Toast the sourdough.","Melt the butter in a non-stick pan over medium-low heat. Pour in the eggs and wait 20 seconds.","Slowly push the eggs from the edges into the middle with a spatula. Keep going until they are almost set but still glossy.","Take the pan off the heat and gently fold in the salmon and most of the chives.","Spoon onto the toast and sprinkle with the rest of the chives."],"tp":"Add the salmon off the heat. Cooking it makes it tough and very salty.","dt":["pescatarian"],"c":442,"p":34,"cb":26.3,"ft":21.7,"ps":68,"i":[["Eggs",26,150,"3 eggs","egg",50],["Smoked salmon",136,40,"2 slices",null,null],["Sourdough bread",85,60,"1 thick slice",null,null],["Butter",29,5,"1 tsp",null,null],["Fresh chives",144,3,"1 tbsp chopped",null,null]]},{"k":"pes-c-lunch","f":"pescatarian","d":"C","m":"lunch","n":"Salmon and potato fishcakes with salad","ds":"Golden fishcakes made with tinned salmon and potato, with a lemony salad.","pr":20,"ck":25,"st":["Peel the potato and cut it into chunks. Boil in salted water for 12 to 15 minutes until soft. Drain well and mash with a fork. Let it cool for 5 minutes.","Drain the salmon and flake it, removing any large bones and skin (the small soft bones are fine to eat and full of calcium).","Beat the egg in a cup and add half of it to the potato (keep the rest for another meal). Mix in the salmon, the finely sliced spring onion, half the lemon juice, salt and pepper.","Shape into 3 patties about 2 cm thick and press each side into the breadcrumbs.","Heat 1 teaspoon of the oil in a non-stick pan over medium heat. Cook the fishcakes for 3 to 4 minutes each side until golden and hot in the middle.","Toss the salad leaves and halved tomatoes with the rest of the oil and lemon juice and serve with the fishcakes."],"tp":"Chill the shaped fishcakes for 15 minutes before cooking and they hold together better.","dt":["pescatarian","dairyfree"],"c":387,"p":28.2,"cb":30.8,"ft":15.4,"ps":69,"i":[["Canned pink salmon, drained",145,90,"1 small can (105 g size)",null,null],["Potato",50,150,"1 medium potato",null,null],["Egg",26,25,"1/2 egg, beaten",null,null],["Spring onion",59,10,"1 stem",null,null],["Dry breadcrumbs",146,15,"2 tbsp",null,null],["Mixed salad leaves",47,40,"1 large handful",null,null],["Cherry tomatoes",28,60,"5 tomatoes",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"pes-c-dinner","f":"pescatarian","d":"C","m":"dinner","n":"Baked barramundi with lemon potatoes and greens","ds":"Lemon and garlic baked barramundi with crispy potatoes and green beans. An easy Sunday roast.","pr":10,"ck":40,"st":["Heat the oven to 210°C (190°C fan) and line a tray with baking paper.","Scrub the potato and cut it into 2 cm cubes. Toss with half the oil, salt and pepper on the tray. Roast for 25 minutes, turning once.","Rub the fish with the rest of the oil, the crushed garlic, half the lemon juice, salt and pepper.","Push the potatoes to the side, put the fish and green beans on the tray, and roast for 12 to 15 minutes until the fish is white all the way through and flakes easily.","Squeeze over the rest of the lemon juice and scatter with chopped parsley."],"tp":"Check the fish at 12 minutes. Thinner fillets cook faster.","dt":["pescatarian","glutenfree","dairyfree"],"c":382,"p":39.5,"cb":27.1,"ft":10.8,"ps":70,"i":[["Barramundi fillet",143,170,"1 large fillet",null,null],["Potato",72,200,"1 large potato",null,null],["Green beans",52,100,"1 large handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Lemon",36,15,"juice of 1/2 lemon",null,null],["Garlic",11,6,"2 cloves",null,null],["Flat-leaf parsley",90,5,"a few sprigs",null,null]]},{"k":"pes-c-snack","f":"pescatarian","d":"C","m":"snack","n":"Mango lassi smoothie","ds":"A creamy mango, yoghurt and milk smoothie.","pr":5,"ck":0,"st":["Put the mango, yoghurt, milk and a pinch of cardamom or cinnamon in a blender.","Blend on high for 30 seconds until smooth and frothy.","Pour into a glass and drink cold."],"tp":"Frozen mango cubes make it thick and icy without needing ice.","dt":["vegetarian","pescatarian","glutenfree"],"c":210,"p":12.8,"cb":28.2,"ft":3.9,"ps":71,"i":[["Mango, fresh or frozen",147,100,"1/2 mango",null,null],["Greek yoghurt, low fat",2,100,"1/3 cup",null,null],["Reduced fat milk",1,150,"2/3 cup",null,null],["Cardamom or cinnamon",25,0.5,"a pinch",null,null]]},{"k":"hp-a-breakfast","f":"highprotein","d":"A","m":"breakfast","n":"Spinach, mushroom and feta omelette","ds":"A fluffy omelette packed with mushrooms, spinach and feta, with a slice of toast.","pr":5,"ck":8,"st":["Slice the mushrooms thinly. Whisk the eggs in a bowl with a pinch of pepper (no salt, the feta is salty). Put the bread in the toaster.","Heat half the oil in a non-stick frying pan over medium heat. Cook the mushrooms for 3 minutes until golden, add the spinach and stir until wilted. Tip them onto a plate.","Add the rest of the oil to the pan and pour in the eggs. Tilt the pan so the egg covers the base.","As the edges set, pull them into the middle with a spatula and let the runny egg flow to the edges. Cook for about 2 minutes.","When the top is nearly set, spoon the mushrooms and spinach over one half and crumble on the feta.","Fold the omelette in half, cook for 30 seconds more and slide it onto a plate. Serve with the toast."],"tp":"Wipe mushrooms with a damp paper towel instead of washing them. They stay firm and brown better.","dt":["vegetarian","pescatarian"],"c":399,"p":30.7,"cb":16.9,"ft":22,"ps":72,"i":[["Eggs",26,150,"3 eggs","egg",50],["Mushrooms",83,60,"3 mushrooms",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Feta, reduced fat",86,20,"2 tbsp crumbled",null,null],["Wholegrain bread",96,40,"1 slice",null,null],["Olive oil",19,4,"1 tsp",null,null]]},{"k":"hp-a-lunch","f":"highprotein","d":"A","m":"lunch","n":"Tuna, white bean and rocket salad","ds":"A Tuscan-style salad of tuna, cannellini beans, rocket and tomatoes with crusty bread.","pr":10,"ck":0,"st":["Rinse the cannellini beans in a sieve under cold water and drain well.","Halve the cherry tomatoes, slice the onion as thin as you can and roughly chop the parsley.","In a large bowl, whisk the olive oil, lemon juice and a pinch of salt and pepper.","Add the beans, tomatoes, onion and parsley and toss through the dressing.","Drain the tuna and break it into chunks over the salad. Add the rocket and toss gently.","Serve with the sourdough, toasted if you like."],"tp":"Let the beans sit in the dressing for 10 minutes before adding the rocket. They soak up the flavour.","dt":["pescatarian","dairyfree"],"c":476,"p":47.3,"cb":36.1,"ft":11.9,"ps":73,"i":[["Tuna in springwater, drained",56,130,"1 large can (185 g size)",null,null],["Canned cannellini beans, drained",99,120,"1/2 can",null,null],["Rocket",100,40,"2 handfuls",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Red onion",73,20,"2 thin slices",null,null],["Flat-leaf parsley",90,5,"a few sprigs",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Sourdough bread",85,40,"1 small slice",null,null]]},{"k":"hp-a-dinner","f":"highprotein","d":"A","m":"dinner","n":"Baked barramundi with lemon potatoes and greens","ds":"Lemon and garlic baked barramundi with crispy potatoes and green beans. An easy Sunday roast.","pr":10,"ck":40,"st":["Heat the oven to 210°C (190°C fan) and line a tray with baking paper.","Scrub the potato and cut it into 2 cm cubes. Toss with half the oil, salt and pepper on the tray. Roast for 25 minutes, turning once.","Rub the fish with the rest of the oil, the crushed garlic, half the lemon juice, salt and pepper.","Push the potatoes to the side, put the fish and green beans on the tray, and roast for 12 to 15 minutes until the fish is white all the way through and flakes easily.","Squeeze over the rest of the lemon juice and scatter with chopped parsley."],"tp":"Check the fish at 12 minutes. Thinner fillets cook faster.","dt":["pescatarian","glutenfree","dairyfree"],"c":382,"p":39.5,"cb":27.1,"ft":10.8,"ps":74,"i":[["Barramundi fillet",143,170,"1 large fillet",null,null],["Potato",72,200,"1 large potato",null,null],["Green beans",52,100,"1 large handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Lemon",36,15,"juice of 1/2 lemon",null,null],["Garlic",11,6,"2 cloves",null,null],["Flat-leaf parsley",90,5,"a few sprigs",null,null]]},{"k":"hp-a-snack","f":"highprotein","d":"A","m":"snack","n":"Cottage cheese with pineapple","ds":"Creamy cottage cheese with sweet pineapple. A retro snack packed with protein.","pr":2,"ck":0,"st":["Spoon the cottage cheese into a bowl.","Drain the pineapple and add it on top.","Stir together, or eat as is."],"tp":"Fresh pineapple works too and is even better in summer.","dt":["vegetarian","pescatarian","glutenfree"],"c":159,"p":15,"cb":15.9,"ft":3,"ps":75,"i":[["Cottage cheese, reduced fat",107,120,"1/2 cup",null,null],["Pineapple pieces, drained",82,100,"2/3 cup",null,null]]},{"k":"hp-b-breakfast","f":"highprotein","d":"B","m":"breakfast","n":"Cheesy omelette with toast","ds":"A fluffy three egg omelette with cheese, tomato and spinach.","pr":5,"ck":6,"st":["Crack the eggs into a bowl, add a pinch of salt and pepper and whisk until smooth.","Dice the tomato. Put the bread in the toaster.","Spray a non-stick frying pan with oil and heat over medium heat. Pour in the eggs and tilt the pan so they cover the base.","Cook for about 1 minute until the edges start to set. Use a spatula to pull the set edges into the middle and let the runny egg flow underneath.","When the top is almost set but still slightly wet, scatter the cheese, tomato and spinach over one half.","Fold the empty half over the filling. Cook for 30 seconds more so the cheese melts, then slide onto a plate with the toast."],"tp":"Use whatever leftover vegetables are in the fridge. Mushrooms, capsicum and onion all work.","dt":["vegetarian","pescatarian"],"c":384,"p":29.9,"cb":18,"ft":20.5,"ps":76,"i":[["Eggs",26,150,"3 eggs","egg",50],["Cheddar, reduced fat, grated",65,20,"1/4 cup",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Baby spinach",27,30,"1 handful",null,null],["Wholemeal bread",22,40,"1 slice",null,null],["Olive oil spray",19,2,"a quick spray",null,null]]},{"k":"hp-b-lunch","f":"highprotein","d":"B","m":"lunch","n":"Chicken souvlaki pita with tzatziki","ds":"Lemon and oregano chicken in a warm pita with homemade tzatziki, tomato and onion.","pr":15,"ck":10,"st":["Cut the chicken into 3 cm cubes. In a bowl, mix with the olive oil, half the lemon juice, the oregano and a pinch of salt and pepper. Leave for 5 minutes (or up to a day in the fridge).","Make the tzatziki: grate half the cucumber, squeeze out the water with your hands, and mix it with the yoghurt, the rest of the lemon juice, the garlic (crushed) and a pinch of salt.","Thread the chicken onto skewers if you have them, or cook the pieces loose. Heat a frying pan or grill pan over medium-high heat and cook for 8 to 10 minutes, turning, until charred on the edges and cooked through.","Slice the tomato, the rest of the cucumber and the red onion. Shred the lettuce.","Warm the pita in the dry pan for 30 seconds each side so it is soft and bendy.","Spread the tzatziki over the pita, add the lettuce, tomato, cucumber, onion and chicken, and roll it up. Wrap the bottom in baking paper to hold it together."],"tp":"Soak wooden skewers in water for 30 minutes first so they do not burn.","dt":[],"c":445,"p":42.1,"cb":44.5,"ft":8.9,"ps":77,"i":[["Chicken breast",6,130,"1 small breast",null,null],["Pita bread",87,70,"1 large pita",null,null],["Greek yoghurt, low fat",2,60,"1/4 cup",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Tomato",33,60,"1/2 tomato",null,null],["Red onion",73,20,"2 thin slices",null,null],["Cos lettuce",32,20,"1 leaf",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Garlic",11,4,"1 small clove",null,null],["Dried oregano",21,1,"1 tsp",null,null]]},{"k":"hp-b-dinner","f":"highprotein","d":"B","m":"dinner","n":"Lean beef spaghetti bolognese","ds":"The family classic, made with lean mince and extra vegetables hidden in the sauce.","pr":10,"ck":25,"st":["Fill a large saucepan with water, add a pinch of salt and put it on to boil for the pasta.","Peel and finely chop the onion and garlic. Grate the carrot and zucchini on the large holes of a grater.","Heat the olive oil in a frying pan over medium heat. Add the onion and cook for 3 minutes until soft.","Add the mince and turn the heat up to medium-high. Break it up with a wooden spoon and cook for 5 minutes until browned all over with no pink left.","Stir in the garlic, carrot and zucchini and cook for 2 minutes.","Pour in the canned tomatoes, add the oregano and 50 ml of water. Season with a pinch of salt and pepper. Bring to a simmer, then turn the heat down to low and cook for 10 to 15 minutes, stirring now and then, until thick.","While the sauce simmers, add the spaghetti to the boiling water and cook for the time on the packet (usually 9 to 11 minutes). Drain.","Put the spaghetti in a bowl, spoon the sauce over and finish with the grated parmesan."],"tp":"The sauce freezes well for up to 3 months. Cook a big batch and freeze it in single serves.","dt":[],"c":654,"p":52.1,"cb":70,"ft":15.4,"ps":78,"i":[["Lean beef mince (5% fat)",14,150,"150 g",null,null],["Spaghetti, dry",15,80,"80 g (a bundle the width of a 20c coin)",null,null],["Canned diced tomatoes",16,200,"1/2 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["Carrot",9,50,"1/2 small carrot",null,null],["Zucchini",18,70,"1/3 medium zucchini",null,null],["Garlic",11,6,"1 to 2 cloves",null,null],["Olive oil",19,5,"1 tsp",null,null],["Parmesan, grated",20,10,"1 1/2 tbsp",null,null],["Dried oregano or Italian herbs",21,1,"1 tsp",null,null]]},{"k":"hp-b-snack","f":"highprotein","d":"B","m":"snack","n":"Edamame and a cheese stick","ds":"Salty, steamed edamame beans with a cheese stick. High protein, zero effort.","pr":1,"ck":4,"st":["Put the frozen edamame in a microwave-safe bowl with 1 tablespoon of water.","Cover and microwave on high for 3 minutes, stirring halfway, until hot.","Drain, sprinkle with a pinch of salt and eat with the cheese stick."],"tp":"Find frozen edamame in the frozen vegetable section or at Asian grocers.","dt":["vegetarian","pescatarian","glutenfree"],"c":229,"p":22.4,"cb":11.4,"ft":11.8,"ps":79,"i":[["Frozen shelled edamame",113,150,"1 cup",null,null],["Cheddar cheese stick",65,20,"1 cheese stick",null,null]]},{"k":"hp-c-breakfast","f":"highprotein","d":"C","m":"breakfast","n":"Smoked salmon scrambled eggs on sourdough","ds":"Soft scrambled eggs with smoked salmon and chives on toasted sourdough.","pr":5,"ck":6,"st":["Whisk the eggs with pepper (no salt, the salmon is salty). Chop the chives. Tear the salmon into strips.","Toast the sourdough.","Melt the butter in a non-stick pan over medium-low heat. Pour in the eggs and wait 20 seconds.","Slowly push the eggs from the edges into the middle with a spatula. Keep going until they are almost set but still glossy.","Take the pan off the heat and gently fold in the salmon and most of the chives.","Spoon onto the toast and sprinkle with the rest of the chives."],"tp":"Add the salmon off the heat. Cooking it makes it tough and very salty.","dt":["pescatarian"],"c":442,"p":34,"cb":26.3,"ft":21.7,"ps":80,"i":[["Eggs",26,150,"3 eggs","egg",50],["Smoked salmon",136,40,"2 slices",null,null],["Sourdough bread",85,60,"1 thick slice",null,null],["Butter",29,5,"1 tsp",null,null],["Fresh chives",144,3,"1 tbsp chopped",null,null]]},{"k":"hp-c-lunch","f":"highprotein","d":"C","m":"lunch","n":"Tuna, olive and feta pasta salad","ds":"Wholemeal pasta tossed with tuna, cherry tomatoes, olives, spinach and feta.","pr":10,"ck":12,"st":["Cook the pasta in boiling salted water for the time on the packet. Drain and rinse under cold water until cool.","Halve the tomatoes, dice the cucumber and slice the olives.","Whisk the olive oil and lemon juice with salt and pepper in a large bowl.","Add the pasta, tomatoes, cucumber, olives and spinach and toss through the dressing.","Drain the tuna, flake it over the top and crumble on the feta."],"tp":"Keeps for 2 days in the fridge. Add the spinach just before eating so it stays fresh.","dt":["pescatarian"],"c":546,"p":48.9,"cb":46.3,"ft":15.4,"ps":81,"i":[["Wholemeal pasta, dry",111,70,"3/4 cup",null,null],["Tuna in springwater, drained",56,130,"1 large can (185 g size)",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Baby spinach",27,30,"1 handful",null,null],["Kalamata olives",94,15,"4 olives",null,null],["Feta, reduced fat",86,15,"1 heaped tbsp crumbled",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"hp-c-dinner","f":"highprotein","d":"C","m":"dinner","n":"Sunday roast chicken thighs with vegetables","ds":"Crispy herb chicken thighs roasted on one tray with potato, pumpkin and green beans.","pr":15,"ck":40,"st":["Heat the oven to 200°C (180°C fan). Line a large tray with baking paper.","Peel the potato and cut it into 3 cm chunks. Peel the pumpkin and cut it into chunks the same size. Smaller pieces cook faster.","Put the potato and pumpkin on the tray, drizzle with half the oil, sprinkle with half the rosemary, salt and pepper, and toss with your hands. Roast for 15 minutes.","Meanwhile, rub the chicken thighs with the remaining oil, rosemary, crushed garlic, lemon juice, salt and pepper.","Take the tray out, turn the vegetables over and push them to the sides. Put the chicken in the middle. Roast for another 20 to 25 minutes.","In the last 8 minutes, add the green beans to the tray.","The chicken is ready when the juices run clear when you cut into the thickest part. The vegetables should be golden and soft when pierced with a knife.","Rest the chicken for 3 minutes, then serve with the vegetables and any juices from the tray poured over."],"tp":"Roast extra chicken and vegetables. They make an easy lunch the next day.","dt":["glutenfree","dairyfree"],"c":454,"p":41.2,"cb":34.5,"ft":14.4,"ps":82,"i":[["Chicken thigh fillets, skinless",49,170,"2 small fillets",null,null],["Potato",50,180,"1 medium potato",null,null],["Pumpkin",51,150,"1 large wedge",null,null],["Green beans",52,80,"1 handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh or dried rosemary",53,1,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"hp-c-snack","f":"highprotein","d":"C","m":"snack","n":"Cottage cheese, crackers and tomato","ds":"Cottage cheese piled on crackers with sliced tomato and cracked pepper.","pr":3,"ck":0,"st":["Halve the cherry tomatoes.","Spread the cottage cheese over the crackers.","Top with the tomatoes and a good grind of black pepper."],"tp":"A pinch of dried chilli flakes or everything bagel seasoning on top is great here.","dt":["vegetarian","pescatarian"],"c":236,"p":21.6,"cb":20.9,"ft":5.4,"ps":83,"i":[["Cottage cheese, reduced fat",107,150,"2/3 cup",null,null],["Wholegrain crackers",64,20,"3 crackers",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null]]},{"k":"gf-a-breakfast","f":"glutenfree","d":"A","m":"breakfast","n":"Veggie omelette with sweet potato hash","ds":"A three egg omelette with mushrooms and spinach, with crispy paprika sweet potato in place of toast.","pr":10,"ck":15,"st":["Peel the sweet potato and cut it into 1 cm cubes. Put them in a microwave-safe bowl with 1 tablespoon of water, cover and microwave on high for 4 minutes until just soft.","Heat 1 teaspoon of the olive oil in a non-stick frying pan over medium-high heat. Add the sweet potato, sprinkle with the paprika and a pinch of salt, and cook for 5 to 6 minutes, turning now and then, until golden at the edges. Tip it onto your plate.","Slice the mushrooms and the spring onion.","Add the rest of the olive oil to the pan and cook the mushrooms for 3 minutes until soft. Add the spinach and stir for 30 seconds until it wilts.","Crack the eggs into a bowl, add a pinch of salt and pepper and whisk with a fork.","Turn the heat down to medium-low. Pour the eggs over the vegetables and leave them for 2 minutes. Gently lift the edges with a spatula so the runny egg flows underneath.","When the top is almost set, scatter over the spring onion, fold the omelette in half and slide it onto the plate next to the sweet potato hash."],"tp":"Cook a big batch of the sweet potato on Sunday. It keeps for 3 days in the fridge and reheats in a hot pan in 2 minutes.","dt":["vegetarian","pescatarian","glutenfree","dairyfree"],"c":387,"p":23.4,"cb":21.5,"ft":21.7,"ps":84,"i":[["Eggs",26,150,"3 eggs","egg",50],["Sweet potato",116,150,"1/2 medium sweet potato",null,null],["Mushrooms",83,60,"3 mushrooms",null,null],["Baby spinach",27,30,"1 handful",null,null],["Spring onion",59,10,"1 stem",null,null],["Olive oil",19,8,"2 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"gf-a-lunch","f":"glutenfree","d":"A","m":"lunch","n":"Greek salad with chicken and quinoa","ds":"A filling Greek salad with grilled chicken, quinoa, olives and feta.","pr":10,"ck":20,"st":["Rinse the quinoa well in a fine sieve (this removes the bitter coating). Put it in a small saucepan with 120 ml of water, bring to the boil, then cover and simmer on low for 12 minutes. Turn off and leave covered for 5 minutes, then fluff with a fork and let it cool.","Season the chicken with salt, pepper and half the oregano. Cook it in a frying pan with a few drops of the oil over medium-high heat for 4 to 5 minutes each side until cooked through. Rest for 3 minutes, then slice.","Cut the cucumber and tomato into chunks and slice the onion thinly.","Whisk the rest of the olive oil with the lemon juice and the remaining oregano.","Put the quinoa in a bowl, add the vegetables and olives, then the chicken. Crumble the feta over and pour on the dressing."],"tp":"Pack the dressing separately if you are making this for work so the salad stays crisp.","dt":["glutenfree"],"c":480,"p":40.9,"cb":31.5,"ft":18.8,"ps":85,"i":[["Chicken breast",6,120,"1 small breast",null,null],["Quinoa, uncooked",93,45,"1/4 cup",null,null],["Cucumber",34,70,"1/2 cucumber",null,null],["Tomato",33,80,"1 small tomato",null,null],["Red onion",73,20,"2 thin slices",null,null],["Kalamata olives",94,20,"5 olives",null,null],["Feta, reduced fat",86,25,"2 tbsp crumbled",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Dried oregano",21,0.5,"a pinch",null,null]]},{"k":"gf-a-dinner","f":"glutenfree","d":"A","m":"dinner","n":"Baked barramundi with lemon potatoes and greens","ds":"Lemon and garlic baked barramundi with crispy potatoes and green beans. An easy Sunday roast.","pr":10,"ck":40,"st":["Heat the oven to 210°C (190°C fan) and line a tray with baking paper.","Scrub the potato and cut it into 2 cm cubes. Toss with half the oil, salt and pepper on the tray. Roast for 25 minutes, turning once.","Rub the fish with the rest of the oil, the crushed garlic, half the lemon juice, salt and pepper.","Push the potatoes to the side, put the fish and green beans on the tray, and roast for 12 to 15 minutes until the fish is white all the way through and flakes easily.","Squeeze over the rest of the lemon juice and scatter with chopped parsley."],"tp":"Check the fish at 12 minutes. Thinner fillets cook faster.","dt":["pescatarian","glutenfree","dairyfree"],"c":382,"p":39.5,"cb":27.1,"ft":10.8,"ps":86,"i":[["Barramundi fillet",143,170,"1 large fillet",null,null],["Potato",72,200,"1 large potato",null,null],["Green beans",52,100,"1 large handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Lemon",36,15,"juice of 1/2 lemon",null,null],["Garlic",11,6,"2 cloves",null,null],["Flat-leaf parsley",90,5,"a few sprigs",null,null]]},{"k":"gf-a-snack","f":"glutenfree","d":"A","m":"snack","n":"Chilli salt edamame","ds":"Steamed edamame beans tossed with salt and chilli flakes.","pr":1,"ck":4,"st":["Put the frozen edamame in a microwave-safe bowl with 1 tablespoon of water.","Cover and microwave on high for 3 minutes, stirring halfway.","Drain and toss with a pinch of salt and chilli flakes."],"tp":"Edamame is one of the highest-protein plant snacks you can buy.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":220,"p":22.5,"cb":15.3,"ft":9.5,"ps":87,"i":[["Frozen shelled edamame",113,200,"1 1/3 cups",null,null],["Chilli flakes",131,0.5,"a pinch",null,null]]},{"k":"gf-b-breakfast","f":"glutenfree","d":"B","m":"breakfast","n":"Greek yoghurt crunch bowl","ds":"Thick Greek yoghurt with berries, almonds, pepitas and chia. Crunchy like muesli, with no oats or grains.","pr":5,"ck":0,"st":["Put the frozen berries in a small bowl and microwave for 40 to 60 seconds until just thawed and juicy. Or put them in the fridge the night before.","Roughly chop the almonds on a board.","Spoon the Greek yoghurt into a bowl and stir in the chia seeds.","Tip the berries and their juice over the yoghurt.","Scatter the chopped almonds and pepitas on top and drizzle with the honey."],"tp":"Most plain Greek yoghurt is gluten free, but check the label says so.","dt":["vegetarian","pescatarian","glutenfree"],"c":434,"p":23.9,"cb":32.9,"ft":19.8,"ps":88,"i":[["Greek yoghurt, low fat",2,200,"3/4 cup",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Almonds",125,15,"12 almonds",null,null],["Pepitas (pumpkin seeds)",115,10,"1 tbsp",null,null],["Chia seeds",4,10,"2 tsp",null,null],["Honey",5,10,"1 1/2 tsp",null,null]]},{"k":"gf-b-lunch","f":"glutenfree","d":"B","m":"lunch","n":"Chickpea, quinoa and roast veg bowl with tahini","ds":"Roasted chickpeas and vegetables on quinoa with a lemony tahini dressing.","pr":10,"ck":25,"st":["Heat the oven to 200°C (180°C fan) and line a tray with baking paper.","Drain and rinse the chickpeas and pat them dry with paper towel. Peel the pumpkin and cut it into 2 cm cubes. Cut the broccoli into small florets. Cover the edamame with boiling water for 3 minutes, then drain.","Toss the chickpeas and pumpkin with the oil, paprika and a pinch of salt on the tray. Roast for 15 minutes, add the broccoli, and roast for 10 minutes more.","Meanwhile rinse the quinoa and simmer it in 130 ml of water, covered, for 12 minutes. Leave covered off the heat for 5 minutes and fluff with a fork.","Whisk the tahini with the lemon juice and 1 to 2 tablespoons of water until smooth and pourable. It will look thick and lumpy at first, keep whisking.","Put the spinach and quinoa in a bowl, top with the roast vegetables, chickpeas and edamame, and drizzle with the tahini dressing."],"tp":"Roast a double batch of chickpeas. They make a crunchy snack on their own.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":619,"p":30.6,"cb":59.9,"ft":23.8,"ps":89,"i":[["Canned chickpeas, drained",104,120,"2/3 cup",null,null],["Quinoa, uncooked",93,50,"1/4 cup",null,null],["Pumpkin",51,120,"1 wedge",null,null],["Broccoli",8,80,"1 cup of small florets",null,null],["Frozen shelled edamame",113,60,"1/3 cup",null,null],["Baby spinach",27,30,"1 handful",null,null],["Tahini",121,15,"3 tsp",null,null],["Lemon juice",36,15,"3 tsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Smoked paprika",98,1,"1/2 tsp",null,null]]},{"k":"gf-b-dinner","f":"glutenfree","d":"B","m":"dinner","n":"Beef and bean chilli with rice","ds":"A big-batch chilli that stretches lean mince with kidney beans. Cheap, filling and freezes well.","pr":10,"ck":25,"st":["Start the rice: rinse it and put it in a saucepan with 120 ml of water. Bring to the boil, turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Leave it covered off the heat.","Peel and dice the onion. Heat the oil in a frying pan over medium heat and cook the onion for 3 minutes until soft.","Add the mince, turn the heat up and break it up with a spoon. Cook for 5 minutes until browned.","Stir in the chilli powder and cumin and cook for 30 seconds until it smells toasty.","Add the tomatoes, the drained kidney beans and 50 ml of water. Season with salt and pepper. Simmer on low for 12 to 15 minutes until thick.","Serve the chilli over the rice with a spoonful of yoghurt on top."],"tp":"Not a fan of heat? Leave out the chilli powder and use smoked paprika instead.","dt":["glutenfree"],"c":569,"p":42.3,"cb":68.4,"ft":10.4,"ps":90,"i":[["Lean beef mince (5% fat)",14,120,"120 g",null,null],["Canned red kidney beans, drained",60,100,"1/2 cup",null,null],["Canned diced tomatoes",16,150,"1/3 can",null,null],["Brown onion",17,60,"1/2 small onion",null,null],["White rice, uncooked",7,60,"1/4 cup plus 1 tbsp",null,null],["Natural yoghurt",61,30,"1 heaped tbsp",null,null],["Chilli powder",62,1,"1/2 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Olive oil",19,3,"a drizzle",null,null]]},{"k":"gf-b-snack","f":"glutenfree","d":"B","m":"snack","n":"Cottage cheese with pineapple","ds":"Creamy cottage cheese with sweet pineapple. A retro snack packed with protein.","pr":2,"ck":0,"st":["Spoon the cottage cheese into a bowl.","Drain the pineapple and add it on top.","Stir together, or eat as is."],"tp":"Fresh pineapple works too and is even better in summer.","dt":["vegetarian","pescatarian","glutenfree"],"c":159,"p":15,"cb":15.9,"ft":3,"ps":91,"i":[["Cottage cheese, reduced fat",107,120,"1/2 cup",null,null],["Pineapple pieces, drained",82,100,"2/3 cup",null,null]]},{"k":"gf-c-breakfast","f":"glutenfree","d":"C","m":"breakfast","n":"Smoked salmon, egg and avocado rice cakes","ds":"Crunchy rice cakes with smashed avocado, smoked salmon and a soft boiled egg. A Sunday cafe breakfast at home.","pr":5,"ck":8,"st":["Bring a small saucepan of water to the boil. Lower the eggs in gently with a spoon and boil them for 8 minutes.","Lift the eggs into a bowl of cold water and leave them for 2 minutes, then peel and slice them.","While the eggs cook, scoop the avocado into a bowl, add the lemon juice and a pinch of salt and pepper, and mash with a fork.","Spread the avocado over the rice cakes.","Top with the smoked salmon and the sliced egg, then snip or scatter the chives over the top. Eat straight away so the rice cakes stay crunchy."],"tp":"Pick rice cakes labelled gluten free. Boil extra eggs: peeled, they keep for 2 days in a sealed container in the fridge.","dt":["pescatarian","glutenfree","dairyfree"],"c":435,"p":30.6,"cb":24.5,"ft":23,"ps":92,"i":[["Plain rice cakes",84,30,"3 rice cakes","rice cake",10],["Eggs",26,100,"2 eggs","egg",50],["Smoked salmon",136,60,"3 slices",null,null],["Avocado",31,50,"1/3 avocado",null,null],["Lemon juice",36,5,"1 tsp",null,null],["Fresh chives",144,3,"1 tbsp chopped",null,null]]},{"k":"gf-c-lunch","f":"glutenfree","d":"C","m":"lunch","n":"Halloumi, pumpkin and quinoa salad","ds":"Golden halloumi with roast pumpkin, quinoa, rocket and pepitas.","pr":10,"ck":25,"st":["Heat the oven to 200°C (180°C fan). Peel the pumpkin and cut it and the zucchini into 2 cm cubes. Toss with half the oil, salt and pepper on a lined tray and roast for 20 to 25 minutes until golden.","Rinse the quinoa, then simmer it in 130 ml of water in a covered saucepan for 12 minutes. Leave covered off the heat for 5 minutes and fluff with a fork.","Toast the pepitas in a dry frying pan over medium heat for 2 minutes until they start to pop. Tip them out.","Slice the halloumi into 1 cm slices. In the same pan over medium-high heat, cook for 1 to 2 minutes each side until golden.","Rinse and drain the chickpeas. Mix the quinoa, chickpeas, pumpkin, zucchini and rocket in a bowl. Whisk the remaining oil with the balsamic and toss it through.","Top with the halloumi and pepitas. Eat while the halloumi is warm."],"tp":"Halloumi goes squeaky and rubbery when it cools, so cook it last.","dt":["vegetarian","pescatarian","glutenfree"],"c":685,"p":33.9,"cb":54.4,"ft":33.3,"ps":93,"i":[["Halloumi",114,70,"3 to 4 slices",null,null],["Quinoa, uncooked",93,50,"1/4 cup",null,null],["Pumpkin",51,150,"1 large wedge",null,null],["Zucchini",18,70,"1/3 zucchini",null,null],["Canned chickpeas, drained",104,80,"1/2 cup",null,null],["Rocket",100,30,"1 large handful",null,null],["Pepitas (pumpkin seeds)",115,10,"1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Balsamic vinegar",48,10,"2 tsp",null,null]]},{"k":"gf-c-dinner","f":"glutenfree","d":"C","m":"dinner","n":"Sunday roast chicken thighs with vegetables","ds":"Crispy herb chicken thighs roasted on one tray with potato, pumpkin and green beans.","pr":15,"ck":40,"st":["Heat the oven to 200°C (180°C fan). Line a large tray with baking paper.","Peel the potato and cut it into 3 cm chunks. Peel the pumpkin and cut it into chunks the same size. Smaller pieces cook faster.","Put the potato and pumpkin on the tray, drizzle with half the oil, sprinkle with half the rosemary, salt and pepper, and toss with your hands. Roast for 15 minutes.","Meanwhile, rub the chicken thighs with the remaining oil, rosemary, crushed garlic, lemon juice, salt and pepper.","Take the tray out, turn the vegetables over and push them to the sides. Put the chicken in the middle. Roast for another 20 to 25 minutes.","In the last 8 minutes, add the green beans to the tray.","The chicken is ready when the juices run clear when you cut into the thickest part. The vegetables should be golden and soft when pierced with a knife.","Rest the chicken for 3 minutes, then serve with the vegetables and any juices from the tray poured over."],"tp":"Roast extra chicken and vegetables. They make an easy lunch the next day.","dt":["glutenfree","dairyfree"],"c":454,"p":41.2,"cb":34.5,"ft":14.4,"ps":94,"i":[["Chicken thigh fillets, skinless",49,170,"2 small fillets",null,null],["Potato",50,180,"1 medium potato",null,null],["Pumpkin",51,150,"1 large wedge",null,null],["Green beans",52,80,"1 handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh or dried rosemary",53,1,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"gf-c-snack","f":"glutenfree","d":"C","m":"snack","n":"Greek yoghurt with honey and pistachios","ds":"Thick yoghurt with a drizzle of honey and crunchy pistachios.","pr":2,"ck":0,"st":["Spoon the yoghurt into a bowl.","Roughly chop the pistachios.","Scatter the pistachios over the yoghurt and drizzle with the honey."],"tp":"Add a pinch of cinnamon for a baklava-style flavour.","dt":["vegetarian","pescatarian","glutenfree"],"c":239,"p":13.9,"cb":19.5,"ft":10.5,"ps":95,"i":[["Greek yoghurt, low fat",2,150,"2/3 cup",null,null],["Pistachios, shelled",102,15,"1 small handful",null,null],["Honey",5,8,"1 tsp",null,null]]},{"k":"df-a-breakfast","f":"dairyfree","d":"A","m":"breakfast","n":"Baked beans and eggs on toast","ds":"The cheapest high-protein breakfast there is. Warm beans, eggs and toast in 8 minutes.","pr":2,"ck":8,"st":["Put the baked beans in a small saucepan over low heat, or in a microwave-safe bowl covered with a plate (microwave for 90 seconds, stir halfway).","Put the bread in the toaster.","Spray a non-stick frying pan with oil and heat it over medium heat. Crack in the eggs and cook for 3 minutes for a runny yolk, or 4 to 5 minutes for a firm yolk. Put a lid on the pan to cook the tops.","Put the toast on a plate, spoon the hot beans over and top with the eggs. Season with pepper."],"tp":"Pick the salt-reduced baked beans. They taste the same and have less salt.","dt":["vegetarian","pescatarian","dairyfree"],"c":448,"p":27.1,"cb":47.2,"ft":12.8,"ps":96,"i":[["Baked beans in tomato sauce",67,150,"about 1/3 of a 420 g can",null,null],["Eggs",26,100,"2 eggs","egg",50],["Wholemeal bread",22,70,"2 slices",null,null],["Olive oil spray",19,2,"a quick spray",null,null]]},{"k":"df-a-lunch","f":"dairyfree","d":"A","m":"lunch","n":"Teriyaki chicken rice bowl","ds":"Sticky soy and honey chicken with rice, broccoli and carrot. Great hot or cold from a lunchbox.","pr":10,"ck":20,"st":["Rinse the rice in a sieve under cold water until the water runs mostly clear. Put it in a small saucepan with 140 ml (just over 1/2 cup) of water.","Bring the rice to the boil, then turn the heat to the lowest setting, put the lid on and cook for 12 minutes. Turn the heat off and leave the lid on for 5 more minutes.","While the rice cooks, cut the chicken into bite-sized pieces about 2 cm wide. Peel and finely chop the garlic. Peel the carrot and cut it into thin sticks. Cut the broccoli into small florets.","In a cup, mix the soy sauce, honey and chopped garlic. This is your teriyaki sauce.","Heat the sesame oil in a frying pan over medium-high heat. Add the chicken and cook for 5 to 6 minutes, turning the pieces, until golden on the outside and white all the way through.","Add the carrot and broccoli with 2 tablespoons of water. Cook for 3 minutes, stirring, until the broccoli is bright green and just tender.","Pour in the teriyaki sauce and stir for 1 minute until it bubbles and coats everything.","Spoon the rice into a bowl, add the chicken and vegetables on top and sprinkle with sesame seeds."],"tp":"Cut into the thickest piece of chicken to check it is cooked: no pink inside.","dt":["dairyfree"],"c":543,"p":45.1,"cb":65.4,"ft":9,"ps":97,"i":[["Chicken breast",6,150,"1 small breast",null,null],["White rice, uncooked",7,70,"1/3 cup",null,null],["Broccoli",8,100,"1 cup of small florets",null,null],["Carrot",9,60,"1/2 medium carrot",null,null],["Salt-reduced soy sauce",10,15,"3 tsp",null,null],["Honey",5,10,"1 1/2 tsp",null,null],["Garlic",11,5,"1 clove",null,null],["Sesame oil",12,5,"1 tsp",null,null],["Sesame seeds",13,3,"1 tsp",null,null]]},{"k":"df-a-dinner","f":"dairyfree","d":"A","m":"dinner","n":"Honey soy salmon with rice and greens","ds":"Pan-fried salmon with a sticky honey soy glaze, brown rice and broccolini.","pr":5,"ck":30,"st":["Rinse the brown rice and simmer it in 170 ml of water, covered, for 25 minutes. Leave covered off the heat for 5 minutes.","Mix the soy sauce, honey, grated garlic and grated ginger in a cup.","Pat the salmon dry with paper towel. Heat a non-stick frying pan over medium-high heat. Put the salmon in skin side down and cook for 4 minutes without moving it, until the skin is crisp.","Flip the salmon and cook for 2 minutes. Pour the sauce around it and let it bubble for 1 to 2 minutes, spooning it over the fish, until sticky. The salmon is done when it flakes easily but is still slightly pink in the centre.","While the salmon cooks, steam or microwave the broccolini with 1 tablespoon of water for 2 to 3 minutes until bright green.","Serve the salmon on the rice with the broccolini, pour over the pan sauce and sprinkle with sesame seeds."],"tp":"Turn the heat down if the honey starts to burn. It catches quickly.","dt":["pescatarian","dairyfree"],"c":569,"p":39.4,"cb":48.5,"ft":22.7,"ps":98,"i":[["Salmon fillet, skin on",141,140,"1 fillet",null,null],["Brown rice, uncooked",37,55,"1/4 cup",null,null],["Broccolini",142,100,"about 1/2 bunch (6 stems)",null,null],["Salt-reduced soy sauce",10,15,"3 tsp",null,null],["Honey",5,10,"1 1/2 tsp",null,null],["Garlic",11,4,"1 clove",null,null],["Fresh ginger",105,4,"2 cm piece",null,null],["Sesame seeds",13,3,"1 tsp",null,null]]},{"k":"df-a-snack","f":"dairyfree","d":"A","m":"snack","n":"Chilli salt edamame","ds":"Steamed edamame beans tossed with salt and chilli flakes.","pr":1,"ck":4,"st":["Put the frozen edamame in a microwave-safe bowl with 1 tablespoon of water.","Cover and microwave on high for 3 minutes, stirring halfway.","Drain and toss with a pinch of salt and chilli flakes."],"tp":"Edamame is one of the highest-protein plant snacks you can buy.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":220,"p":22.5,"cb":15.3,"ft":9.5,"ps":99,"i":[["Frozen shelled edamame",113,200,"1 1/3 cups",null,null],["Chilli flakes",131,0.5,"a pinch",null,null]]},{"k":"df-b-breakfast","f":"dairyfree","d":"B","m":"breakfast","n":"Tofu scramble on toast","ds":"Golden, savoury scrambled tofu with spinach and tomatoes. An egg-free take on scrambled eggs.","pr":5,"ck":8,"st":["Drain the tofu and pat it dry with paper towel.","Heat the oil in a non-stick frying pan over medium heat. Crumble the tofu into the pan with your fingers into small, uneven pieces.","Sprinkle in the turmeric, garlic powder, salt and pepper and stir so the tofu turns yellow. Cook for 4 minutes, stirring, until heated through and starting to brown.","Halve the cherry tomatoes and add them with the spinach. Stir for 2 minutes until the spinach wilts.","Add the soy milk and stir for 30 seconds. This makes it creamy, like scrambled eggs.","Toast the bread and pile the scramble on top."],"tp":"A pinch of black salt (kala namak) from an Indian grocer gives it a real egg flavour.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":525,"p":35.7,"cb":32.2,"ft":25.3,"ps":100,"i":[["Firm tofu",117,200,"2/3 block",null,null],["Wholegrain bread",96,70,"2 slices",null,null],["Baby spinach",27,40,"1 large handful",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Soy milk",118,20,"1 tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Ground turmeric",119,0.5,"1/4 tsp",null,null],["Garlic powder",120,0.5,"a pinch",null,null]]},{"k":"df-b-lunch","f":"dairyfree","d":"B","m":"lunch","n":"Prawn and avocado poke bowl","ds":"Garlic prawns on sushi-style rice with edamame, cucumber, carrot and avocado.","pr":15,"ck":20,"st":["Rinse the rice well and cook it in 130 ml of water: bring to the boil, cover and cook on the lowest heat for 12 minutes, then leave covered off the heat for 5 minutes. Stir in the rice vinegar and let it cool slightly.","Microwave the edamame with 1 tablespoon of water, covered, for 2 minutes. Drain.","Peel the carrot and grate it or cut it into thin matchsticks. Slice the cucumber and avocado.","Heat the sesame oil in a frying pan over medium-high heat. Add the prawns and chopped garlic and cook for 1 to 2 minutes each side until the prawns turn pink and curl into a C shape. Do not overcook or they go rubbery.","Put the rice in a bowl and arrange the prawns, edamame, cucumber, carrot and avocado on top in sections.","Drizzle with soy sauce and sprinkle with sesame seeds."],"tp":"Prawns are cooked when they are pink all over and curled into a C. A tight O shape means overcooked.","dt":["pescatarian","dairyfree"],"c":540,"p":40.3,"cb":58.3,"ft":14.6,"ps":101,"i":[["Raw peeled prawns",139,130,"8 to 10 prawns",null,null],["White rice, uncooked",7,65,"1/3 cup",null,null],["Frozen shelled edamame",113,50,"1/3 cup",null,null],["Cucumber",34,60,"1/2 cucumber",null,null],["Carrot",9,50,"1/2 small carrot",null,null],["Avocado",31,40,"1/4 avocado",null,null],["Salt-reduced soy sauce",10,15,"3 tsp",null,null],["Rice vinegar",140,5,"1 tsp",null,null],["Sesame oil",12,3,"1/2 tsp",null,null],["Sesame seeds",13,3,"1 tsp",null,null],["Garlic",11,4,"1 clove",null,null]]},{"k":"df-b-dinner","f":"dairyfree","d":"B","m":"dinner","n":"Lamb kofta with tabouli and hummus","ds":"Spiced lamb kofta with a fresh parsley and bulgur tabouli and a spoon of hummus.","pr":20,"ck":12,"st":["Put the fine bulgur in a bowl and pour over 90 ml of boiling water. Cover with a plate and leave for 15 minutes until soft. Fluff with a fork. (Coarse bulgur needs simmering instead: check the packet.)","Finely grate the onion. In another bowl, mix the lamb mince with the grated onion, cumin, coriander, a pinch of salt and pepper. Squish it together with clean hands for 1 minute.","Divide the mince into 4 and shape each piece into a sausage about 10 cm long. Push onto skewers if you like.","Heat a frying pan or grill over medium-high heat with a light brush of the olive oil. Cook the kofta for 8 to 10 minutes, turning every 2 minutes, until browned all over and cooked through.","While they cook, finely chop the parsley, tomato and cucumber. Mix them with the bulgur, the lemon juice, the rest of the olive oil and a pinch of salt. That is your tabouli.","Serve the kofta on the tabouli with the hummus on the side."],"tp":"Wet your hands before shaping the kofta so the mince does not stick.","dt":["dairyfree"],"c":499,"p":35.7,"cb":35.5,"ft":21.3,"ps":102,"i":[["Lean lamb mince",88,130,"130 g",null,null],["Fine bulgur (cracked wheat), dry",89,45,"1/4 cup",null,null],["Flat-leaf parsley",90,25,"1 big handful",null,null],["Tomato",33,80,"1 small tomato",null,null],["Cucumber",34,50,"1/3 cucumber",null,null],["Brown onion",17,30,"1/4 onion",null,null],["Hummus",91,30,"1 heaped tbsp",null,null],["Olive oil",19,5,"1 tsp",null,null],["Lemon juice",36,15,"3 tsp",null,null],["Ground cumin",63,1,"1/2 tsp",null,null],["Ground coriander",92,1,"1/2 tsp",null,null]]},{"k":"df-b-snack","f":"dairyfree","d":"B","m":"snack","n":"Tuna and crackers with cherry tomatoes","ds":"Lemon pepper tuna piled on crackers with cherry tomatoes.","pr":3,"ck":0,"st":["Drain the tuna and mix it with the lemon juice and plenty of black pepper.","Halve the tomatoes.","Pile the tuna onto the crackers and eat with the tomatoes."],"tp":"Flavoured tuna tins are easy, but check the label: some are packed in oil and have twice the calories.","dt":["pescatarian","dairyfree"],"c":184,"p":21.1,"cb":14.7,"ft":3.4,"ps":103,"i":[["Tuna in springwater, drained",56,70,"1 small can (95 g size)",null,null],["Wholegrain crackers",64,20,"3 crackers",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Lemon juice",36,5,"a squeeze",null,null]]},{"k":"df-c-breakfast","f":"dairyfree","d":"C","m":"breakfast","n":"Berry chia overnight oats","ds":"Oats soaked in soy milk with chia seeds, plant protein and berries. Make the night before.","pr":5,"ck":0,"st":["Put the oats and chia seeds in a jar that holds at least 600 ml.","Add the protein powder, then pour in the soy milk and maple syrup and stir very well until no powder lumps are left and the chia seeds are not clumped at the bottom.","Tip the frozen berries on top.","Put the lid on and refrigerate overnight, or for at least 4 hours. Give it a stir after the first 10 minutes if you can, to stop the chia clumping.","In the morning, stir and add the peanut butter on top."],"tp":"Keeps for 3 days in the fridge, so make several at once.","dt":["vegan","vegetarian","pescatarian","dairyfree"],"c":654,"p":40.2,"cb":61.5,"ft":23.6,"ps":104,"i":[["Rolled oats",0,60,"2/3 cup",null,null],["Soy milk",118,250,"1 cup",null,null],["Chia seeds",4,15,"1 tbsp",null,null],["Plant protein powder, unflavoured or vanilla",126,25,"25 g (scoop sizes vary)",null,null],["Frozen mixed berries",3,80,"1/2 cup",null,null],["Peanut butter, no added sugar",23,10,"2 tsp",null,null],["Maple syrup",45,10,"1 1/2 tsp",null,null]]},{"k":"df-c-lunch","f":"dairyfree","d":"C","m":"lunch","n":"Tuna, white bean and rocket salad","ds":"A Tuscan-style salad of tuna, cannellini beans, rocket and tomatoes with crusty bread.","pr":10,"ck":0,"st":["Rinse the cannellini beans in a sieve under cold water and drain well.","Halve the cherry tomatoes, slice the onion as thin as you can and roughly chop the parsley.","In a large bowl, whisk the olive oil, lemon juice and a pinch of salt and pepper.","Add the beans, tomatoes, onion and parsley and toss through the dressing.","Drain the tuna and break it into chunks over the salad. Add the rocket and toss gently.","Serve with the sourdough, toasted if you like."],"tp":"Let the beans sit in the dressing for 10 minutes before adding the rocket. They soak up the flavour.","dt":["pescatarian","dairyfree"],"c":476,"p":47.3,"cb":36.1,"ft":11.9,"ps":105,"i":[["Tuna in springwater, drained",56,130,"1 large can (185 g size)",null,null],["Canned cannellini beans, drained",99,120,"1/2 can",null,null],["Rocket",100,40,"2 handfuls",null,null],["Cherry tomatoes",28,80,"6 to 8 tomatoes",null,null],["Red onion",73,20,"2 thin slices",null,null],["Flat-leaf parsley",90,5,"a few sprigs",null,null],["Olive oil",19,7,"1 1/2 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null],["Sourdough bread",85,40,"1 small slice",null,null]]},{"k":"df-c-dinner","f":"dairyfree","d":"C","m":"dinner","n":"Sunday roast chicken thighs with vegetables","ds":"Crispy herb chicken thighs roasted on one tray with potato, pumpkin and green beans.","pr":15,"ck":40,"st":["Heat the oven to 200°C (180°C fan). Line a large tray with baking paper.","Peel the potato and cut it into 3 cm chunks. Peel the pumpkin and cut it into chunks the same size. Smaller pieces cook faster.","Put the potato and pumpkin on the tray, drizzle with half the oil, sprinkle with half the rosemary, salt and pepper, and toss with your hands. Roast for 15 minutes.","Meanwhile, rub the chicken thighs with the remaining oil, rosemary, crushed garlic, lemon juice, salt and pepper.","Take the tray out, turn the vegetables over and push them to the sides. Put the chicken in the middle. Roast for another 20 to 25 minutes.","In the last 8 minutes, add the green beans to the tray.","The chicken is ready when the juices run clear when you cut into the thickest part. The vegetables should be golden and soft when pierced with a knife.","Rest the chicken for 3 minutes, then serve with the vegetables and any juices from the tray poured over."],"tp":"Roast extra chicken and vegetables. They make an easy lunch the next day.","dt":["glutenfree","dairyfree"],"c":454,"p":41.2,"cb":34.5,"ft":14.4,"ps":106,"i":[["Chicken thigh fillets, skinless",49,170,"2 small fillets",null,null],["Potato",50,180,"1 medium potato",null,null],["Pumpkin",51,150,"1 large wedge",null,null],["Green beans",52,80,"1 handful",null,null],["Olive oil",19,8,"2 tsp",null,null],["Garlic",11,6,"2 cloves",null,null],["Fresh or dried rosemary",53,1,"1 tsp",null,null],["Lemon juice",36,10,"2 tsp",null,null]]},{"k":"df-c-snack","f":"dairyfree","d":"C","m":"snack","n":"Chocolate peanut butter smoothie","ds":"A thick chocolate smoothie with soy milk, banana, peanut butter and plant protein.","pr":5,"ck":0,"st":["Put the soy milk, banana, protein powder, peanut butter, cocoa and ice in a blender.","Blend on high for 30 to 45 seconds until completely smooth.","Pour into a tall glass and drink straight away."],"tp":"Use a frozen banana instead of ice for a thicker, creamier smoothie.","dt":["vegan","vegetarian","pescatarian","glutenfree","dairyfree"],"c":470,"p":37.4,"cb":33.4,"ft":18.5,"ps":107,"i":[["Soy milk",118,300,"1 1/4 cups",null,null],["Banana",24,80,"2/3 banana",null,null],["Peanut butter, no added sugar",23,15,"3 tsp",null,null],["Plant protein powder, unflavoured or vanilla",126,30,"30 g (scoop sizes vary)",null,null],["Cocoa powder",54,5,"2 tsp",null,null],["Ice cubes",55,50,"3 ice cubes",null,null]]}]$json$::jsonb)),
ins as (
  insert into public.recipes (id, slug, family, day_type, meal_type, name, description, prep_minutes, cook_minutes, steps, tip, diets, calories, protein_g, carbs_g, fats_g, position)
  select md5('unfnshd-meal-library:' || (r->>'k'))::uuid, r->>'k', r->>'f', r->>'d', r->>'m', r->>'n', r->>'ds', (r->>'pr')::int, (r->>'ck')::int, r->'st', r->>'tp',
    array(select jsonb_array_elements_text(r->'dt')), (r->>'c')::int, (r->>'p')::numeric, (r->>'cb')::numeric, (r->>'ft')::numeric, (r->>'ps')::int
  from d on conflict (id) do update set slug = excluded.slug, family = excluded.family, day_type = excluded.day_type, meal_type = excluded.meal_type, name = excluded.name, description = excluded.description, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, steps = excluded.steps, tip = excluded.tip, diets = excluded.diets, calories = excluded.calories, protein_g = excluded.protein_g, carbs_g = excluded.carbs_g, fats_g = excluded.fats_g, position = excluded.position
  returning id
)
insert into public.recipe_ingredients (id, recipe_id, position, label, food_id, grams, measure, each_label, each_grams, calories, protein_g, carbs_g, fats_g)
select md5('unfnshd-meal-library:' || ((r->>'k') || ':ing:' || (x.ord - 1)))::uuid, md5('unfnshd-meal-library:' || (r->>'k'))::uuid, x.ord - 1, x.e->>0, fd.id, (x.e->>2)::numeric, x.e->>3, x.e->>4, (x.e->>5)::numeric,
  round(fd.calories * (x.e->>2)::numeric / 100, 1), round(fd.protein_g * (x.e->>2)::numeric / 100, 1), round(fd.carbs_g * (x.e->>2)::numeric / 100, 1), round(fd.fats_g * (x.e->>2)::numeric / 100, 1)
from d cross join lateral jsonb_array_elements(r->'i') with ordinality as x(e, ord)
cross join f
join public.foods fd on fd.id = ((f.ids)->>((x.e->>1)::int))::uuid
on conflict (id) do update set recipe_id = excluded.recipe_id, position = excluded.position, label = excluded.label, food_id = excluded.food_id, grams = excluded.grams, measure = excluded.measure, each_label = excluded.each_label, each_grams = excluded.each_grams, calories = excluded.calories, protein_g = excluded.protein_g, carbs_g = excluded.carbs_g, fats_g = excluded.fats_g;

-- Ingredients a recipe no longer has.
delete from public.recipe_ingredients ri using public.recipes r, (values ('bal-a-breakfast', 6), ('bal-a-lunch', 9), ('bal-a-dinner', 10), ('bal-a-snack', 4), ('bal-b-breakfast', 6), ('bal-b-lunch', 10), ('bal-b-dinner', 12), ('bal-b-snack', 3), ('bal-c-breakfast', 7), ('bal-c-lunch', 8), ('bal-c-dinner', 8), ('bal-c-snack', 5), ('bud-a-breakfast', 5), ('bud-a-lunch', 6), ('bud-a-dinner', 9), ('bud-a-snack', 3), ('bud-b-breakfast', 4), ('bud-b-lunch', 7), ('bud-b-dinner', 7), ('bud-b-snack', 3), ('bud-c-breakfast', 6), ('bud-c-lunch', 8), ('bud-c-dinner', 7), ('bud-c-snack', 4), ('med-a-breakfast', 7), ('med-a-lunch', 11), ('med-a-dinner', 11), ('med-a-snack', 4), ('med-b-breakfast', 5), ('med-b-lunch', 10), ('med-b-dinner', 10), ('med-b-snack', 4), ('med-c-breakfast', 10), ('med-c-lunch', 9), ('med-c-dinner', 12), ('med-c-snack', 3), ('veg-a-breakfast', 6), ('veg-a-lunch', 10), ('veg-a-dinner', 11), ('veg-a-snack', 3), ('veg-b-breakfast', 7), ('veg-b-lunch', 7), ('veg-b-dinner', 11), ('veg-b-snack', 2), ('veg-c-breakfast', 8), ('veg-c-lunch', 9), ('veg-c-dinner', 10), ('veg-c-snack', 7), ('vgn-a-breakfast', 8), ('vgn-a-lunch', 10), ('vgn-a-dinner', 11), ('vgn-a-snack', 5), ('vgn-b-breakfast', 7), ('vgn-b-lunch', 10), ('vgn-b-dinner', 11), ('vgn-b-snack', 2), ('vgn-c-breakfast', 9), ('vgn-c-lunch', 9), ('vgn-c-dinner', 11), ('vgn-c-snack', 6), ('pes-a-breakfast', 7), ('pes-a-lunch', 11), ('pes-a-dinner', 8), ('pes-a-snack', 4), ('pes-b-breakfast', 5), ('pes-b-lunch', 9), ('pes-b-dinner', 10), ('pes-b-snack', 2), ('pes-c-breakfast', 5), ('pes-c-lunch', 9), ('pes-c-dinner', 7), ('pes-c-snack', 4), ('hp-a-breakfast', 6), ('hp-a-lunch', 9), ('hp-a-dinner', 7), ('hp-a-snack', 2), ('hp-b-breakfast', 6), ('hp-b-lunch', 11), ('hp-b-dinner', 10), ('hp-b-snack', 2), ('hp-c-breakfast', 5), ('hp-c-lunch', 9), ('hp-c-dinner', 8), ('hp-c-snack', 3), ('gf-a-breakfast', 7), ('gf-a-lunch', 10), ('gf-a-dinner', 7), ('gf-a-snack', 2), ('gf-b-breakfast', 6), ('gf-b-lunch', 10), ('gf-b-