ins as (
  insert into public.meal_plan_library (id, slug, family, family_name, sex, goal, name, description, ref_weight_kg, ref_height_cm, ref_age, activity_factor, maintenance_calories,
    target_calories, target_protein_g, target_carbs_g, target_fats_g, avg_calories, avg_protein_g, avg_carbs_g, avg_fats_g, position)
  select md5('unfnshd-meal-library:' || (p->>'s'))::uuid, p->>'s', p->>'f', p->>'fn', p->>'x', p->>'g', p->>'n', p->>'ds', (p->>'w')::numeric, (p->>'h')::numeric, (p->>'a')::int, (p->>'af')::numeric, (p->>'mc')::int,
    (p->'t'->>0)::int, (p->'t'->>1)::int, (p->'t'->>2)::int, (p->'t'->>3)::int, (p->'v'->>0)::int, (p->'v'->>1)::int, (p->'v'->>2)::int, (p->'v'->>3)::int, ord::int - 1
  from d on conflict (id) do update set slug = excluded.slug, family = excluded.family, family_name = excluded.family_name, sex = excluded.sex, goal = excluded.goal, name = excluded.name, description = excluded.description, ref_weight_kg = excluded.ref_weight_kg, ref_height_cm = excluded.ref_height_cm, ref_age = excluded.ref_age, activity_factor = excluded.activity_factor, maintenance_calories = excluded.maintenance_calories, target_calories = excluded.target_calories, target_protein_g = excluded.target_protein_g, target_carbs_g = excluded.target_carbs_g, target_fats_g = excluded.target_fats_g, avg_calories = excluded.avg_calories, avg_protein_g = excluded.avg_protein_g, avg_carbs_g = excluded.avg_carbs_g, avg_fats_g = excluded.avg_fats_g, position = excluded.position
  returning id
)
insert into public.meal_plan_library_items (id, plan_id, day_type, meal_type, position, recipe_id, servings)
select md5('unfnshd-meal-library:' || ((p->>'s') || ':' || r.day_type || ':' || r.meal_type))::uuid, md5('unfnshd-meal-library:' || (p->>'s'))::uuid, r.day_type, r.meal_type,
  array_position(array['breakfast','lunch','dinner','snack'], r.meal_type) - 1, r.id, (p->'sv'->>r.day_type)::numeric
from d join public.recipes r on r.family = p->>'f'
on conflict (id) do update set plan_id = excluded.plan_id, day_type = excluded.day_type, meal_type = excluded.meal_type, position = excluded.position, recipe_id = excluded.recipe_id, servings = excluded.servings;
commit;
